local yf=jb.n(EQd[247]..tf)
if yf>=(xf.max or 0)then
return nil
end
if jb.freeBoard(tf)and not(vf and vf.ignoreFree)then
return nil
end
local zf=wf.UpgradeRoom[tf]
if zf and not jb.roomOwned(zf)then
return nil
end
local Af=xf.currency or EQd[175]
if Af==EQd[248]then
return nil
end
if Af==EQd[249]and not jb.has(EQd[250])then
return nil
end
if tf==EQd[251]or tf==EQd[252]or tf==EQd[253]then
return nil
end
if Af==EQd[254]and tf~=EQd[255]then
local Bf=wf.Upgrades.EggCash
if Bf and jb.n(EQd[230])<(Bf.max or 0)then
return nil
end
end
local Cf=wf.UpgradeCost(tf,yf)
local Df
if tf==EQd[256]then
Df=uf/(1+yf)
elseif tf==EQd[257]then
Df=uf*(wf.TickInterval(yf)/wf.TickInterval(yf+1)-1)
elseif tf==EQd[258]then
Df=uf*(wf.WormCashMultiplier(yf+1)/wf.WormCashMultiplier(yf)-1)
elseif tf==EQd[227]then
Df=uf*(wf.GrubCashMult(yf+1)/wf.GrubCashMult(yf)-1)
elseif tf==EQd[259]then
Df=uf*(wf.CoalCashMult(yf+1)/wf.CoalCashMult(yf)-1)
elseif tf==EQd[255]then
Df=uf*(wf.EggCashMult(yf+1)/wf.EggCashMult(yf)-1)
elseif tf==EQd[260]or tf==EQd[261]or(tf==EQd[262]and vb.digUpGain and vf and vf.dig)then
local Ef=vf.dig
if not Ef then
return nil
end
local Ff=tonumber(jb.a(EQd[263]))
if not(Ff and Ff>0 and Ff<1)then
Ff=1
end
local Gf=wf.DigInterval(jb.n(EQd[246]))*Ff
local Hf=db.HORIZON/math.max(0.2,Gf)
local If
if tf==EQd[260]then
If=Hf*1
else
