_N=_N+cO*dO*math.clamp(tonumber(fO)or 0,0,1)
end
else
_N=_N+cO*dO
end
end
end
end
end
return _N,aO
end
function vb.luckPoints(gO,hO,iO,jO,kO)
if not(iO and iO>0)then
return 0
end
local lO=vb.m1(EQd[262])
local mO=vb.digExpected(gO,hO*(lO+iO)/lO,true,kO)
return vb.lasting(math.max(0,mO-jO)*kO.n/kO.iv*vb.digShare())
end
function vb.digExpected(nO,oO,pO,qO,rO)
oO=tonumber(oO)or vb.fossilLuck()
local sO,tO=vb.rollProbs(nO,oO)
if not sO then
return 0
end
qO=qO or vb.valCtx()
local uO=math.max(1,qO.n)
local vO=tonumber(jb.PC.SHINY_MULT)or 2
local wO,xO={},{}
for yO,zO in ipairs(tO.list)do
wO[yO]=math.max(0,(tonumber(zO.max)or 0)-jb.n(EQd[244]..nO..EQd[245]..yO))
end
for AO=1,#tO.list do
local CO=AO
while CO>=1 and wO[CO]<=0 do
CO=CO-1
end
if CO>=1 then
xO[CO]=(xO[CO]or 0)+(sO[AO]or 0)
end
end
local DO,FO,GO=0,0,0
for HO= #tO.list,1,-1 do
if wO[HO]>0 then
local IO=(xO[HO]or 0)*uO+GO
local JO=math.min(IO,wO[HO])
GO=IO-JO
if JO>0 then
local KO=JO/uO*(jb.has(EQd[755]..nO..EQd[245]..HO)and vO or 1)
local LO,MO=vb.fossilPoints(tO.list[HO],qO,rO,KO)
DO=DO+KO*LO
FO=FO+KO*MO
end
end
end
if not pO and FO>0 then
DO=DO+vb.luckPoints(nO,oO,FO,DO,qO)
end
return DO
end
function vb.shinyBoost()
local NO=os.clock()
if vb.sbAt and NO-vb.sbAt<5 then
return vb.sbV
end
local OO,PO=false,0
if jb.has(EQd[756])then
OO,PO=pcall(jb.PC.ShinyBoost,cb)
end
PO=OO and tonumber(PO)or 0
vb.sbAt,vb.sbV=NO,(PO and PO==PO and PO>0)and PO or 0
return vb.sbV
end
function vb.shinyPerDig(QO,RO,SO)
local UO,VO=vb.shinyBoost(),jb.PC.Fossils and jb.PC.Fossils[QO]
if UO<=0 or not(VO and type(VO.list)==EQd[106])then
return 0
end
RO=RO or vb.valCtx()
local WO=(tonumber(jb.PC.SHINY_MULT)or 2)-1
local XO,YO=0,0
for ZO,_O in ipairs(VO.list)do
local aP=math.min(jb.n(EQd[244]..QO..EQd[245]..ZO),tonumber(_O.max)or 0)
if aP>0 and not jb.has(EQd[755]..QO..EQd[245]..ZO)then
local bP,cP=pcall(jb.PC.ShinyOdds,QO,ZO)
cP=bP and tonumber(cP)or nil
if cP and cP>0 then
local dP=math.min(1,UO/cP)*aP*WO
local eP,fP=vb.fossilPoints(_O,RO,SO,dP)
XO=XO+dP*eP
YO=YO+dP*fP
end
end
end
if YO>0 then
local gP=vb.fossilLuck()
XO=XO+vb.luckPoints(QO,gP,YO,vb.digExpected(QO,gP,true,RO),RO)
end
return XO
end
function vb.digGain(hP,iP)
iP=tonumber(iP)or(kb.last and tonumber(kb.last.I))or tonumber(jb.income())
local jP=os.clock()
local kP=vb.dgCache[hP]
if kP and kP.I==iP and jP-kP.t<0.5 then
return kP.gain,kP.shiny,kP.fl,kP.flCur,kP.low
end
local lP=vb.valCtx(iP)
if lP.I<=0 then
return 0,0,0,nil,0
end
local mP,nP={},{}
local oP=vb.shinyPerDig(hP,lP,mP)*lP.perFb
local pP=lP.n*vb.digExpected(hP,nil,nil,lP,nP)*lP.perFb+oP
local qP,rP,sP,tP=0,nil,0,0
local uP={}
for vP,wP in ipairs({nP,mP})do
for xP in pairs(wP)do
if not uP[xP]then
uP[xP]=true
local yP=(nP[xP]or 0)*lP.n*lP.perFb
local zP=(mP[xP]or 0)*lP.perFb
local AP=yP+zP
local BP,CP=vb.ctxCap(xP,lP)
local DP,EP=AP,AP
if BP then
EP=AP*math.clamp(tonumber(CP)or 0,0,1)
DP=math.max(math.min(AP,BP),EP)
end
if DP>0 and DP==DP and DP<math.huge then
pP=pP+DP
qP=qP+DP
tP=tP+math.min(EP,DP)
if DP>sP then
sP,rP=DP,xP
end
if AP>0 then
oP=oP+DP*zP/AP
end
end
end
end
end
vb.dgCache[hP]={I=lP.I,t=jP,gain=pP,shiny=oP,fl=qP,flCur=rP,low=tP}
return pP,oP,qP,rP,tP
end
function vb.setLeft(FP,GP)
local HP=jb.PC.Fossils and jb.PC.Fossils[FP]
if not(HP and type(HP.list)==EQd[106])then
return 0
end
local IP=vb.valCtx(GP)
if IP.I<=0 then
return 0
end
local JP=tonumber(jb.PC.SHINY_MULT)or 2
local KP=vb.shinyBoost()>0
local LP=0
for MP,NP in ipairs(HP.list)do
local OP=tonumber(NP.max)or 0
local PP=math.min(jb.n(EQd[244]..FP..EQd[245]..MP),OP)
local QP=jb.has(EQd[755]..FP..EQd[245]..MP)
local RP=vb.fossilPoints(NP,IP)
LP=LP+math.max(0,OP-PP)*RP*(QP and JP or 1)
if KP and not QP then
LP=LP+OP*RP*(JP-1)
end
end
return LP*IP.perFb
end
function vb.digLeft(SP,TP)
TP=tonumber(TP)or(kb.last and tonumber(kb.last.I))or tonumber(jb.income())or 0
local UP=os.clock()
local VP=vb.dlCache
if VP and VP.I==TP and VP.set==SP and UP-VP.t<0.5 then
return VP.v
end
local WP=0
for XP,YP in ipairs(vb.digList or{})do
if YP.set then
WP=WP+(tonumber(vb.setLeft(YP.set,TP))or 0)
end
end
if not(WP>0)then
WP=tonumber(vb.setLeft(SP,TP))or 0
end
vb.dlCache={I=TP,set=SP,t=UP,v=WP}
return WP
end
function vb.lastingCapped(ZP,_P)
local aQ=tonumber(db.HORIZON)or 300
local bQ=math.max(0,tonumber(ZP)or 0)
if bQ~=bQ then
return 0
end
_P=tonumber(_P)
if not _P or _P~=_P or _P<0 then
_P=math.huge
end
if bQ*aQ<=_P then
return bQ*aQ*0.5
end
return _P-_P*_P/(2*bQ*aQ)
end
function vb.digUpGain(cQ,dQ,eQ)
local fQ=vb.valCtx(eQ)
if fQ.I<=0 then
return 0
end
if cQ==EQd[260]then
return math.max(0,vb.perDig(1)-fQ.n)*vb.digExpected(dQ,nil,nil,fQ)*fQ.perFb/fQ.iv
elseif cQ==EQd[261]then
local gQ=jb.PC
local hQ=jb.n(EQd[246])
local iQ=type(gQ.Upgrades)==EQd[106]and gQ.Upgrades.FasterDigs or nil
local jQ=(type(iQ)==EQd[106]and tonumber(iQ.max))or(hQ+1)
local kQ,lQ=pcall(gQ.DigInterval,hQ)
lQ=kQ and tonumber(lQ)or nil
if not(lQ and lQ>0)or hQ>=jQ then
return 0
end
local mQ,nQ,oQ,pQ,qQ=vb.digGain(dQ,fQ.I)
local rQ=math.max(0,(tonumber(mQ)or 0)-(tonumber(oQ)or 0)+(tonumber(qQ)or 0))
local sQ=vb.nextTick()
local tQ,uQ={},false
for vQ=1,math.min(jQ-hQ,40)do
local wQ,xQ=pcall(gQ.DigInterval,hQ+vQ)
xQ=wQ and tonumber(xQ)or nil
if not(xQ and xQ>0)then
break
end
local yQ,zQ=pcall(gQ.UpgradeCost,EQd[261],hQ+vQ-1)
zQ=yQ and tonumber(zQ)or nil
if not(zQ and zQ==zQ and zQ>0 and zQ<math.huge)then
uQ,zQ=true,1
end
tQ[vQ]={r=xQ/lQ,cost=zQ}
if not sQ or xQ/lQ<=sQ then
break
end
end
if uQ then
for AQ,BQ in ipairs(tQ)do
BQ.cost=1
end
end
return vb.speedFirst(tQ,rQ,vb.digShare()*(tonumber(gb.digK)or 1),vb.digLeft(dQ,eQ))
elseif cQ==EQd[262]then
local CQ=jb.n(EQd[746])
local DQ,EQ,FQ=pcall(function()
return tonumber(jb.PC.FossilLuck(CQ)),tonumber(jb.PC.FossilLuck(CQ+1))
end)
if not(DQ and EQ and FQ and EQ>0)then
return 0
end
local GQ=vb.fossilLuck()
local HQ=vb.digExpected(dQ,GQ,true,fQ)
return math.max(0,vb.digExpected(dQ,GQ*FQ/EQ,true,fQ)-HQ)*fQ.n/fQ.iv*fQ.perFb
end
return 0
end
vb.BURST_START,vb.BURST_KEEP,vb.BURST_PAY,vb.BURST_PAY_KEEP=60,30,4,3
function vb.burstK(IQ)
local JQ=kb.last
local KQ=JQ and JQ.at
if vb.bkAt~=KQ or type(vb.bk)~=EQd[106]then
vb.bk,vb.bkAt={},KQ
vb.bkHave=jb.n(EQd[175])-vb.reserve()
end
local LQ=vb.bk[IQ]
if LQ then
return LQ
end
local MQ=math.max(tonumber(IQ)or 0,tonumber(vb.bkHave)or 0)
LQ=1/(tonumber(db.MAX_PAYBACK)or 1200)
for NQ,OQ in ipairs((JQ and JQ.opts)or{})do
local PQ,QQ=tonumber(OQ.cost),tonumber(OQ.gain)
if OQ.cur==EQd[175]and not OQ.accel and PQ and QQ and PQ>MQ and PQ<math.huge and QQ/PQ>LQ then
LQ=QQ/PQ
end
end
vb.bk[IQ]=LQ
return LQ
end
function vb.burstPre(RQ,SQ,TQ,UQ)
if not vb.loopOn then
return nil
end
if sb.saving and(sb.saving.cur or EQd[175])==EQd[175]then
return nil
end
SQ=tonumber(SQ)or 0
TQ=math.max(0.05,tonumber(TQ)or vb.digInterval())
if not(SQ>0 and SQ<math.huge)then
return nil
end
local VQ=SQ/TQ
local WQ=vb.cur
local XQ=WQ~=nil and WQ.kind==EQd[757]and WQ.set==RQ
UQ=tonumber(UQ)or(kb.last and tonumber(kb.last.I))or tonumber(jb.income())or 0
if VQ>UQ then
local YQ=jb.n(EQd[175])-vb.reserve()
if YQ<VQ*(XQ and vb.BURST_KEEP or vb.BURST_START)then
return nil
end
end
return VQ,XQ
end
function vb.digBurst(ZQ,_Q,aR,bR,eR)
_Q,aR=tonumber(_Q)or 0,tonumber(aR)or 0
if not(aR>0)then
return false
end
local fR,gR=vb.burstPre(ZQ,_Q,bR,eR)
if not fR then
return false
end
if kb.saving and(tonumber(kb.saving.ratio)or 0)*_Q>aR then
return false
end
local hR=math.clamp(tonumber(gb.digK)or 1,0.5,2)
return aR*hR>=(gR and vb.BURST_PAY_KEEP or vb.BURST_PAY)*_Q*vb.burstK(fR*vb.BURST_KEEP)
end
function vb.digEval(iR,jR,kR)
local lR=jb.PC.Fossils and jb.PC.Fossils[iR]
if not lR or(lR.world or 1)==2 or(lR.currency or EQd[175])~=EQd[175]or not jb.roomOwned(lR.room or EQd[238])then
return nil
end
local mR=tonumber(lR.cost)or 1e300
local oR=mR/kR>jR*0.5
if oR and not vb.burstPre(iR,mR,kR,jR)then
return nil
end
local pR,qR,rR,sR=vb.digGain(iR,jR)
if not(pR>0 and mR/pR<=600)then
return nil
end
local tR=false
if oR then
tR=vb.digBurst(iR,mR,pR,kR,jR)
if not tR then
return nil
end
end
return{set=iR,cost=mR,gain=pR,shiny=qR,floor=rR,floorCur=sR,ratio=pR/mR,burst=tR or nil}
end
function vb.floorWords(uR)
local vR=uR and uR.floorCur
if not(vR and(tonumber(uR.floor)or 0)>=0.5*(tonumber(uR.gain)or math.huge))then
return EQd[146]
end
local wR=vb.kcMod and vb.kcMod[vR]
local xR
if type(wR)==EQd[106]and type(wR.goalWho)==EQd[188]then
local yR,zR=pcall(wR.goalWho,vR)
if yR and type(zR)==EQd[120]and zR~=EQd[146]then
xR=(string.sub(zR,1,4)==EQd[313])and(EQd[383]..string.sub(zR,5))or zR
end
end
if not xR then
local AR=(type(wR)==EQd[106]and wR.name)or(vb.kcWho and vb.kcWho[vR])
AR=(type(AR)==EQd[120]and AR~=EQd[146])and AR or nil
if AR and string.sub(AR,1,4)==EQd[313]then
xR=EQd[383]..string.sub(AR,5)
elseif AR then
xR=EQd[383]..AR..(string.sub(AR,-1)==EQd[758]and EQd[759]or EQd[760])
end
end
return EQd[761]..vR..(xR and(EQd[762]..xR)or EQd[146])
end
function vb.burstBegin(BR)
local CR=vb.burstRun
if CR and CR.set==BR.set then
return
end
if CR then
vb.burstEnd()
end
vb.burstRun={set=BR.set,cost=tonumber(BR.cost)or 0,n=0,t0=os.clock(),fb0=1+jb.n(EQd[222])}
end
function vb.burstEnd()
local DR=vb.burstRun
vb.burstRun=nil
if not DR or(DR.n or 0)<=0 then
return
end
local ER=DR.n*DR.cost
pcall(F.spend,EQd[79],DR.set..EQd[763],ER,EQd[175])
pcall(F.note,EQd[79],string.format(EQd[764],DR.set,DR.n,ib.fmt(ER),ib.fmt(DR.fb0),ib.fmt(1+jb.n(EQd[222]))))
end
function vb.leaveBurst(FR)
if vb.leaving then
return false
end
vb.burstEnd()
local GR,HR=vb.cur,jb.root()
if not(GR and GR.kind==EQd[757]and GR.burst)then
return true
end
if not HR then
return true
end
if not vb.isAt(GR,HR.Position)or vb.inWorld2(HR.Position)then
return true
end
if F.yielding()then
return true
end
local function IR()
return F.inStep==true and not vb.loopOn and F.alive
end
if HR.Anchored or vb.lockN>0 or vb.busyNow()or IR()then
return false
end
local JR=vb.parkJob(HR)
local KR=JR and not JR.here and JR.at
if typeof(KR)~=EQd[315]or vb.inWorld2(KR)then
return false
end
local MR=JR.id==EQd[765]and EQd[766]or JR.id==EQd[767]and EQd[768]or EQd[769]
vb.leaving,vb.cur=true,nil
local PR=pcall(function()
if not vb.floorAt(KR)then
cb:RequestStreamAroundAsync(KR,2)
end
local NR,OR=jb.root(),cb.Character
if not(NR and OR)or NR.Anchored or F.yielding()or vb.lockN>0 or vb.cur~=nil or IR()then
error(EQd[770])
end
NR.AssemblyLinearVelocity=Vector3 .zero
OR:PivotTo(CFrame.new(KR)*NR.CFrame.Rotation)
end)
vb.leaving=false
if not PR then
if vb.cur==nil then
vb.cur=GR
end
return false
end
vb.leftDig()
F.note(EQd[79],EQd[771]..tostring(GR.set)..EQd[772]..MR..EQd[173]..tostring(FR)..EQd[773])
return true
end
function vb.saveZone(QR,RR,SR)
local TR=vb.P()
if type(TR.zones)~=EQd[106]then
TR.zones={}
end
local UR=TR.zones[QR]
if type(UR)==EQd[106]and type(UR.c)==EQd[106]and type(UR.s)==EQd[106]then
local VR,XR=pcall(function()
return(Vector3 .new(UR.c[1],UR.c[2],UR.c[3])-RR.Position).Magnitude<0.5 and(Vector3 .new(UR.s[1],UR.s[2],UR.s[3])-SR).Magnitude<0.5
end)
if VR and XR then
return
end
end
TR.zones[QR]={c={RR:GetComponents()},s={SR.X,SR.Y,SR.Z}}
F.saveSoon()
end
function vb.loadZones()
if vb.zLoaded then
return
end
vb.zLoaded=true
local YR=vb.P().zones
if type(YR)~=EQd[106]then
return
end
local ZR=os.clock()
for _R,aS in pairs(YR)do
if type(_R)==EQd[120]and not vb.zmem[_R]and type(aS)==EQd[106]and type(aS.c)==EQd[106]and#aS.c==12 and type(aS.s)==EQd[106]and#aS.s==3 then
local dS,eS,fS=pcall(function()
local bS={}
for cS=1,12 do
bS[cS]=tonumber(aS.c[cS])or error(EQd[774])
end
return CFrame.new(table.unpack(bS)),Vector3 .new(tonumber(aS.s[1]),tonumber(aS.s[2]),tonumber(aS.s[3]))
end)
if dS and eS and fS then
vb.zmem[_R]={cf=eS,size=fS,t=ZR,saved=true}
end
end
end
end
function vb.digOptions()
local gS=kb.last
if not(eb.dig and gS)then
return{}
end
if vb.digAt==gS.at and vb.digOpts then
return vb.digOpts
end
local hS=os.clock()
local iS=tonumber(gS.I)or jb.income()
local jS=vb.digInterval()
local kS={}
local lS,mS=pcall(nb.zones)
for nS,oS in ipairs((lS and type(mS)==EQd[106])and mS or{})do
local pS,qS,rS=pcall(function()
return oS.zone.CFrame,oS.zone.Size
end)
if pS and qS then
local sS=pcall(vb.saveZone,oS.set,qS,rS)
vb.zmem[oS.set]={cf=qS,size=rS,t=hS,saved=sS}
kS[oS.set]=true
end
end
local tS={}
local uS=(vb.cur and vb.cur.kind==EQd[757])and vb.cur.set or nil
for vS,wS in pairs(vb.zmem)do
if kS[vS]or wS.saved or hS-wS.t<900 or vS==uS then
local xS,yS=pcall(vb.digEval,vS,iS,jS)
if xS and yS then
tS[vS]=yS
else
vb.digRule[vS]=nil
end
end
end
local zS=vb.ratio(EQd[175])
local AS=math.clamp(tonumber(gb.digK)or 1,0.5,2)
local BS=jb.n(EQd[175])
local CS
local DS={}
for ES,FS in pairs(tS)do
local GS=vb.zmem[ES]
local HS=FS.cost/jS
local IS=(BS<FS.cost or(sb.saving and sb.saving.cur==EQd[175]and HS>0.02*iS)or(kb.saving and(tonumber(kb.saving.ratio)or 0)>FS.ratio and HS>0.05*iS))and true or false
local JS=vb.digRule[ES]
if not JS then
JS={v=IS,raw=IS,t=hS}
vb.digRule[ES]=JS
end
if IS~=JS.raw then
JS.raw,JS.t=IS,hS
end
if JS.v~=JS.raw and hS-JS.t>=3 then
JS.v=JS.raw
end
local KS=(FS.gain*AS-FS.cost*zS)/jS
if GS and not JS.v and KS>0 then
local LS=vb.box(GS.cf,GS.size,0)
local MS=EQd[146]
if FS.burst then
if HS<=iS then
MS=EQd[775]..ib.fmt(FS.cost)..EQd[776]..(ES==uS and vb.BURST_PAY_KEEP or vb.BURST_PAY)..EQd[777]
else
CS=CS or vb.reserve()
MS=EQd[778]..ib.fmt(FS.cost)..EQd[779]..ib.fmt(HS*vb.BURST_KEEP+CS)
end
end
local NS=vb.floorWords(FS)
DS[#DS+1]={id=EQd[780]..ES,kind=EQd[757],sys=EQd[757],continuous=true,set=ES,cost=FS.cost,gain=FS.gain,shiny=FS.shiny,k=AS,ratio=FS.ratio,iv=jS,value=KS,stay=30,box=LS,at=vb.standAt(LS),icon=EQd[79],label=EQd[781]..ES..EQd[782],burst=FS.burst,why=string.format(EQd[783],jS,ib.fmt(FS.gain*AS),NS,(NS==EQd[146]and(tonumber(FS.shiny)or 0)>=0.5*FS.gain)and EQd[784]or EQd[146],MS)}
end
end
local OS=vb.burstRun
if OS then
local PS=false
for QS,RS in ipairs(DS)do
if RS.set==OS.set and RS.burst then
PS=true
end
end
if not PS or hS-OS.t0>300 then
vb.burstEnd()
end
end
vb.digOpts,vb.digAt,vb.digList=DS,gS.at,DS
return DS
end
function vb.leaveLoss(SS,TS)
if SS.kind~=EQd[757]or not vb.digEnter or not vb.isAt(SS,TS)then
return 0
end
local US=math.max(vb.lastDigT or-1e9,vb.digEnter)
return SS.value*math.clamp(os.clock()-US,0,SS.iv)*vb.resetFactor()
end
function vb.leftDig()
vb.digEnter,vb.digFirst=nil,false
end
function vb.gate(VS,WS)
if vb.resetFactor()<=0 or not vb.digEnter or(VS.value or 0)<=0 then
return
end
local XS=math.max(vb.lastDigT or-1e9,vb.digEnter)+VS.iv-os.clock()
local YS=math.min(1.5,VS.iv*VS.value/(VS.value+math.max(0,WS.value or 0)))
if XS<=0 or XS>YS then
return
end
local ZS,_S=vb.lastDigT,os.clock()
while vb.lastDigT==ZS and os.clock()-_S<XS+0.15 and vb.go()do
task.wait(0.03)
end
end
function vb.onDig(aT,bT)
local cT=os.clock()
local dT=0
if type(bT)==EQd[106]then
for eT,fT in ipairs(bT)do
if type(fT)==EQd[106]then
local gT=tonumber(fT.n)or 1
if gT==gT and gT>0 then
dT=dT+gT
end
if fT.shiny then
vb.sbAt,vb.digOpts=nil,nil
table.clear(vb.dgCache)
end
end
end
end
vb.gotSum=vb.gotSum+dT
vb.expSum=vb.expSum+vb.perDig()
local hT=vb.burstRun
if hT and aT==hT.set then
hT.n=hT.n+1
end
vb.digs=vb.digs+1
vb.stats.digs=vb.stats.digs+1
gb.totals.digs=(tonumber(gb.totals.digs)or 0)+1
local iT=vb.cur
if vb.digFirst and vb.digEnter and iT and iT.kind==EQd[757]and(aT==nil or aT==iT.set)then
vb.digFirst=false
local jT=0.8*vb.num(EQd[741],0.15)
vb.ema(EQd[745],math.min(1.5,math.max(0,cT-vb.digEnter-jT)/iT.iv),0.25)
end
vb.lastDigT=cT
end
function vb.learnTick(kT,lT,mT)
kT,lT,mT=tonumber(kT),tonumber(lT),tonumber(mT)or 0.3
if not(kT and lT and kT>0 and lT>0 and lT==lT and mT>0)then
return
end
local nT,oT,qT,rT=vb.digTicks(kT)
local sT=lT/qT-nT
if rT<vb.FRAME and sT<0.9 then
sT=math.clamp(sT,0,0.9)
vb.ema(EQd[743],1-(1-sT)^(1/nT),mT,0,0.3)
return
end
local tT=math.max(1,math.floor(lT/qT+0.5))
local uT
if tT==nT then
uT=lT/(nT+oT)
else
for vT=1,math.min(tT+1,60)do
local wT,xT=vb.digTicks(kT,lT/vT)
if wT==vT then
local yT=lT/(vT+xT)
if vb.digTicks(kT,yT)~=vT then
yT=lT/vT
end
if not uT or math.abs(yT/qT-1)<math.abs(uT/qT-1)then
uT=yT
end
end
end
if not uT then
return
end
end
if math.abs(uT/qT-1)<0.25 then
vb.ema(EQd[742],uT,mT,0.03,0.2)
end
end
function vb.digMeter()
local zT=os.clock()
local AT=vb.cur
local BT=vb.meter
