BT=nil
end
vb.meter=BT
local CT=jb.root()
local DT=AT and AT.kind==EQd[757]and CT and vb.digEnter~=nil and(vb.lastDigT or-1e9)>=vb.digEnter and vb.isAt(AT,CT.Position)
if not DT then
if BT then
BT.last,BT.wasIn,BT.pEst,BT.pT=zT,false,0,0
end
return
end
local ET=vb.gameInterval()
local function FT()
return{set=AT.set,got=0,exp=0,inT=0,last=zT,inAt=zT,wasIn=true,pT=0,digSeen=vb.lastDigT,gotAt=vb.gotSum,expAt=vb.expSum,digN=0,digAt=vb.digs,gi=ET}
end
if not BT or math.abs(ET-(tonumber(BT.gi)or ET))>1e-6*ET then
vb.meter=FT()
return
end
local GT,HT=zT-BT.last,BT.wasIn
BT.last,BT.inAt,BT.wasIn=zT,zT,true
if not HT or GT>0.5 then
BT.pT,BT.digSeen,BT.gotAt,BT.expAt,BT.digAt=0,vb.lastDigT,vb.gotSum,vb.expSum,vb.digs
return
end
BT.pT=BT.pT+GT
if(vb.lastDigT or-1e9)>(BT.digSeen or-1e9)then
BT.inT,BT.got,BT.exp=BT.inT+BT.pT,BT.got+(vb.gotSum-BT.gotAt),BT.exp+(vb.expSum-BT.expAt)
BT.digN=(BT.digN or 0)+(vb.digs-(BT.digAt or vb.digs))
BT.pT,BT.digSeen,BT.gotAt,BT.expAt,BT.digAt=0,vb.lastDigT,vb.gotSum,vb.expSum,vb.digs
end
if BT.inT>=120 and BT.exp>0 and(BT.digN or 0)>0 then
if BT.got>0 then
local IT=BT.digN>=100
local JT=ET
local KT=BT.inT/BT.digN
if BT.digN>=30 then
local LT,MT=pcall(vb.learnTick,JT,KT,IT and 0.3 or 0.1)
if not LT then
vb.logErr(EQd[785]..tostring(MT))
end
end
local NT=math.clamp(BT.got/BT.exp,0.2,5)
local OT=IT and 0.5 or 0.15
gb.digK=math.clamp((tonumber(gb.digK)or 1)*(1-OT)+NT*OT,0.5,2)
local PT,QT,RT=vb.digTicks(JT)
F.log(1,EQd[786],string.format(EQd[787]..EQd[788]..EQd[789],BT.got/BT.inT,BT.digN/BT.inT,BT.got/BT.digN,BT.exp/BT.digN/JT,1/JT,BT.exp/BT.digN,math.floor(PT),RT,QT*100,1/((PT+QT)*RT),gb.digK))
vb.digOpts=nil
table.clear(vb.dgCache)
F.saveSoon()
end
vb.meter=FT()
end
end
