PU[#PU+1]=RU
end
end
vb.gone=PU
local SU={}
for TU,UU in pairs(vb.spawned)do
SU[#SU+1]=UU
end
for VU,WU in ipairs(NU:GetChildren())do
if WU:IsA(EQd[316])and not vb.skip[WU]then
local XU=true
local YU=vb.claimed[WU]
if YU then
if OU-YU<0.6 then
XU=false
else
vb.claimed[WU]=nil
local ZU=(vb.tries[WU]or 0)+1
vb.tries[WU]=ZU
if ZU>=2 then
vb.skip[WU],XU=true,false
end
end
end
