_U,aV=pcall(WU.GetPivot,WU)
end
if _U and aV then
local cV=aV.Position
local dV,eV,fV=cV,false,nil
for gV,hV in ipairs(SU)do
local iV,jV=hV.pos.X-cV.X,hV.pos.Z-cV.Z
if iV*iV+jV*jV<=2.25 then
dV,eV,fV=hV.pos,true,hV.golden
break
end
end
for kV,lV in ipairs(PU)do
local mV,nV=lV.p.X-dV.X,lV.p.Z-dV.Z
if mV*mV+nV*nV<=(eV and 0.01 or 2.25)then
XU=false
break
end
end
local oV=vb.lightOf[WU]
if oV==nil then
local pV,qV=pcall(WU.FindFirstChildWhichIsA,WU,EQd[801],true)
oV=(pV and qV)or false
vb.lightOf[WU]=oV
end
if oV then
fV=true
if oV.Enabled==false then
XU=false
end
end
if XU then
MU[#MU+1]={m=WU,p=dV,exact=eV,golden=fV==true}
end
end
end
end
return MU
end
function vb.watchPlot()
