uV=(tV and type(uV)==EQd[106])and uV or{}
local vV= #uV
if vV>rV.peak then
rV.peak,rV.peakAt=vV,sV
elseif vV<rV.peak-1 then
rV.peak,rV.peakAt=vV,sV
end
local wV,xV=vb.wormMax(),vb.spawnRate()
local yV=math.max(0.1,xV-(jb.autoOn(EQd[802])and 1 or 0))
local zV=0
for AV,BV in ipairs(uV)do
if BV.golden then
zV=zV+1
end
end
local CV=vV>=math.max(3,0.6*(rV.top or wV))and vV>=rV.peak-1 and sV-rV.peakAt>=math.max(3,3/xV+0.5)
if CV and vV<wV-1 then
rV.top=vV
elseif rV.top and vV>rV.top then
rV.top=nil
end
local DV=math.min(wV-1,rV.top or(wV-1))
rV.n,rV.M,rV.fs,rV.fnet,rV.gold,rV.list,rV.at,rV.cap=vV,wV,xV,yV,zV,uV,sV,DV
rV.full=vV>=DV or CV
rV.soon=rV.full or(vV+yV*vb.hopFar())>=DV
if CV and vV<wV-2 and not rV.lostNoted then
rV.lostNoted=true
