function vb.cover(LV,MV,NV)
local OV={}
for PV,QV in ipairs(LV)do
OV[#OV+1]=vb.standAt(MV,QV.p)
end
for RV=1,#LV do
local SV=LV[RV]
for TV=RV+1,#LV do
local UV=LV[TV]
local VV,WV=SV.p.X-UV.p.X,SV.p.Z-UV.p.Z
local XV=2*math.min(SV.R,UV.R)
if VV*VV+WV*WV<=XV*XV then
OV[#OV+1]=vb.standAt(MV,(SV.p+UV.p)/2)
end
end
end
local YV,ZV={},{}
for _V=1,NV or 40 do
local aW,bW=nil,0
for cW,dW in ipairs(OV)do
local eW=0
for fW,gW in ipairs(LV)do
if not YV[fW]then
local hW,iW=dW.X-gW.p.X,dW.Z-gW.p.Z
if hW*hW+iW*iW<=gW.R*gW.R then
eW=eW+gW.v
end
end
end
if eW>bW then
aW,bW=cW,eW
end
end
if not aW then
break
end
local jW,kW=OV[aW],{}
for lW,mW in ipairs(LV)do
if not YV[lW]then
local nW,oW=jW.X-mW.p.X,jW.Z-mW.p.Z
if nW*nW+oW*oW<=mW.R*mW.R then
YV[lW]=true
kW[#kW+1]=lW
end
end
end
ZV[#ZV+1]={pos=jW,value=bW,idx=kW}
end
return ZV
end
function vb.sweepJob()
