function vb.sweepRun(zW,AW)
local BW=vb.wormZone()
local CW=os.clock()
local DW,EW=vb.wc.n,vb.wc.amt
local FW,GW,HW=0,0,0
local IW={}
while F.alive and os.clock()-CW<AW and vb.go()do
local JW=vb.readPlot()
if#JW==0 then
break
end
vb.prepPlot(JW)
local KW=vb.cover(JW,BW,1)[1]
if not KW then
break
end
local LW=math.clamp(vb.num(EQd[741],0.15),0.08,0.45)
if FW>0 and KW.value*(zW.f or 1)/(LW+vb.num(EQd[740],0.02))<(zW.thr or 0)then
break
end
local MW=jb.root()
local NW=not(MW and vb.inBox(BW.room,MW.Position))
local OW,PW
if NW and vb.useDrop()then
OW,PW=vb.hopDrop(KW.pos,BW)
else
OW=vb.hop(KW.pos)
end
if not OW then
break
end
FW=FW+1
local QW,RW= #KW.idx,os.clock()
local SW=(tonumber(jb.PC and jb.PC.WORM_RADIUS)or 4.5)+jb.n(EQd[804])+0.5
local TW=0
repeat
task.wait(0.03)
TW=vb.confSince(RW,KW.pos,SW)
local UW=os.clock()-RW
until TW>=QW or(UW>=LW and TW>0)or UW>=0.45 or not vb.go()
local VW=os.clock()-RW
if TW>=QW then
vb.ema(EQd[741],VW*1.25+0.02,0.2,0.08,0.45)
elseif TW>0 then
vb.ema(EQd[741],LW*1.3,0.2,0.08,0.45)
end
if QW>0 and vb.go()then
local WW={}
for XW,YW in ipairs(KW.idx)do
if JW[YW].exact then
WW[#WW+1]=JW[YW].p
end
end
if#WW>0 then
IW[#IW+1]={key=(NW and PW)and EQd[810]or(NW and EQd[811]or EQd[526]),tH=RW,cs=WW}
end
end
local ZW=os.clock()
for _W,aX in ipairs(KW.idx)do
vb.claimed[JW[aX].m]=ZW
end
GW=GW+QW
if TW==0 and vb.go()then
HW=HW+1
if HW>=3 then
F.log(1,EQd[320],EQd[812])
break
end
elseif TW>0 then
HW=0
end
end
local bX=math.max(0,vb.wc.amt-EW)
local cX={c0=DW,a0=EW,taken=GW,hops=FW,secs=os.clock()-CW,t=os.clock(),recs=IW}
vb.pend=cX
local dX=vb.stint
if dX and dX.id==zW.id then
dX.pend=cX
dX.gain=vb.worth(EQd[275],bX)+vb.worth(EQd[249],bX*vb.grubsPerWorm())
dX.text=EQd[813]..ib.fmt(bX)..EQd[814]
end
return FW>0
end
function vb.useDrop()
local eX=vb.P()
if eX.dropV~=2 then
eX.dropIn,eX.dropTried,eX.dropV=nil,nil,2
eX.acceptFirst,eX.acceptRest,eX.nFirst,eX.nRest=nil,nil,nil,nil
eX.cF,eX.nF,eX.hF,eX.cR,eX.nR,eX.cD,eX.nD,eX.hD=0,0,0,0,0,0,0,0
end
local function fX(gX,hX)
hX=tonumber(eX[hX])or 0
return hX>0 and(tonumber(eX[gX])or 0)/hX or nil
end
local iX,jX,kX=fX(EQd[815],EQd[816]),fX(EQd[817],EQd[818]),fX(EQd[819],EQd[820])
if eX.dropIn==true then
if(tonumber(eX.hD)or 0)>=40 and kX and iX and kX<iX+0.03 then
eX.dropIn,eX.dropTried=nil,true
F.log(1,EQd[320],string.format(EQd[821],math.floor(kX*100+0.5),math.floor(iX*100+0.5)))
F.saveSoon()
end
return eX.dropIn==true
end
if eX.dropTried or(tonumber(eX.hF)or 0)<40 or not(iX and jX)then
return false
end
local lX=2*math.sqrt(math.max(0,jX*(1-jX))/math.max(1,tonumber(eX.nF)or 1))
if iX<jX-math.max(0.05,lX)then
eX.dropIn=true
F.log(1,EQd[320],string.format(EQd[822],math.floor(iX*100+0.5),math.floor(jX*100+0.5)))
F.saveSoon()
end
return eX.dropIn==true
end
function vb.hopDrop(mX,nX)
local oX=nX.cf:PointToObjectSpace(mX)
local pX=nX.cf:PointToWorldSpace(Vector3 .new(oX.X,nX.size.Y/2+3,oX.Z))
local sX,tX=pcall(function()
local qX=vb.rp
if not qX then
return true
end
return workspace:Raycast(mX,(pX-mX)+Vector3 .new(0,2.5,0),qX)~=nil
end)
if not sX or tX then
return vb.hop(mX),false
end
if not vb.hop(pX,vb.floorAt(mX))then
return false,false
end
task.wait(math.clamp(0.5*vb.num(EQd[741],0.15),0.05,0.12))
