if uX.taken>0 then
vb.ema(EQd[806],math.min(1,vX/uX.taken),0.2,0,1)
end
local xX=vb.P()
local yX=uX.recs or{}
local zX={}
for AX,BX in ipairs(vb.mine)do
if BX.p then
