if fsb then
hsb=tostring(gsb.why or(EQd[1282]..Geb.setWord(esb)..EQd[1283]))..EQd[1206]..ib.secs(fsb)
isb=hsb
else
jsb,lsb=Geb.value(esb,asb,nil,bsb)
ksb=Geb.value(esb,asb,nil,bsb,true)
