elseif tsb.held then
usb=string.format(EQd[1289],Geb.setName(tsb.held),ib.secs(math.max(1,Geb.VISIT_DWELL-(os.clock()-Geb.visitAt))))
vsb=EQd[1290]..tsb.held.id
end
if tsb.rem and not tsb.remWhy then
return tsb.rem,nil,usb,vsb
end
if tsb.want then
