return
end
local aJb=ZIb:GetPivot():ToObjectSpace(_Ib.CFrame)
local bJb,cJb=pcall(ZIb.GetScale,ZIb)
local dJb=(bJb and tonumber(cJb)and cJb>0)and 0.9/cJb or 0.9
local eJb=CFrame.new(aJb.Position*dJb)*aJb.Rotation
QHb.tpl={inv=eJb:Inverse(),tr=_Ib.Transparency}
end)
return QHb.tpl
end
function QHb.eye(fJb,gJb)
local hJb=workspace:FindFirstChild(EQd[1579])
local iJb=hJb and hJb:FindFirstChild(EQd[1580])
local jJb=iJb and iJb:FindFirstChild(EQd[1578])
if not(jJb and jJb:IsA(EQd[237]))then
return nil
end
local kJb=QHb.eyeTpl()
local lJb=jJb.CFrame
if kJb then
lJb=lJb*kJb.inv
end
local mJb=lJb.Position
gJb.pos=Vector3 .new(mJb.X,fJb.floor,mJb.Z)
gJb.h=mJb.Y-fJb.floor
local nJb=kJb and kJb.tr or 0
gJb.faded=nJb<0.99 and(jJb.Transparency-nJb)/(1-nJb)>0.5
return gJb
end
function QHb.hud()
local oJb=cb:FindFirstChildOfClass(EQd[216])
local pJb=oJb and oJb:FindFirstChild(EQd[362])
local qJb=pJb and pJb:FindFirstChild(EQd[363])
if qJb and qJb:IsA(EQd[420])and qJb.Visible then
return qJb
end
return nil
end
function QHb.hudState(rJb)
local sJb=rJb:FindFirstChild(EQd[421])
local tJb=(sJb and sJb:IsA(EQd[423]))and sJb.Text or EQd[146]
if tJb:sub(1,4)==EQd[568]then
return EQd[1581]
end
if tJb:find(EQd[1582],1,true)then
return EQd[1583]
end
if tJb:find(EQd[1584],1,true)then
return EQd[1585]
end
if tJb:find(EQd[1586],1,true)then
return EQd[1587]
end
return nil
end
function QHb.hearts(uJb)
local vJb=uJb:FindFirstChild(EQd[424])
if not vJb then
return nil
end
local wJb,xJb=0,0
for yJb=1,7 do
local zJb=vJb:FindFirstChild(QHb.HEART[yJb])
if zJb and zJb:IsA(EQd[420])and zJb.Visible then
xJb=xJb+1
if zJb.BackgroundColor3 .R>0.8 then
wJb=wJb+1
end
end
end
if xJb==0 then
return nil
end
return wJb,xJb
end
function QHb.readBar()
local AJb=QHb.hud()
if not AJb then
return
end
local BJb,CJb=QHb.live,QHb.def()
local DJb=AJb:FindFirstChild(EQd[364])
local EJb=DJb and DJb:FindFirstChild(EQd[365])
if EJb and EJb:IsA(EQd[420])and CJb and tonumber(CJb.hp)then
BJb.hpMax=tonumber(CJb.hp)
BJb.hp=math.clamp(EJb.Size.X.Scale,0,1)*BJb.hpMax
end
local FJb=AJb:FindFirstChild(EQd[1588])
if FJb and FJb:IsA(EQd[423])then
local GJb,HJb=tostring(FJb.Text):match(EQd[1589])
if GJb and HJb then
BJb.deadline=QHb.now()+tonumber(GJb)*60+tonumber(HJb)
BJb.activeAt=BJb.deadline-(tonumber(CJb and CJb.time)or 120)
end
end
end
function QHb.classify(IJb,JJb,KJb)
if IJb.Material~=QHb.NEON or IJb.Transparency>=0.97 then
return nil
end
local LJb=IJb.Color
local MJb,NJb=IJb.Size,IJb.CFrame
local OJb=IJb.Shape
local PJb=LJb.R>=0.78 and LJb.G<=0.51 and LJb.B<=0.51
if OJb==QHb.CYL then
local QJb=NJb.RightVector
if math.abs(QJb.Y)>0.9 then
if MJb.X>0.36 then
return nil
end
local RJb=math.max(MJb.Y,MJb.Z)/2
if not PJb then
if LJb.R>0.9 and LJb.G>0.7 and LJb.G<0.95 and LJb.B<0.5 and math.abs(RJb-3.6)<0.4 then
return EQd[1590]
end
return nil
end
if MJb.X>0.26 then
return nil
end
KJb.x,KJb.z,KJb.r=NJb.X,NJb.Z,RJb
return math.abs(RJb-1.3)<0.15 and EQd[1554]or EQd[1437]
end
if not PJb or MJb.X<3 then
return nil
end
local SJb=math.min(MJb.Y,MJb.Z)
local TJb=MJb.X/2
local UJb=NJb.Position
KJb.ax,KJb.ay,KJb.az=UJb.X-QJb.X*TJb,UJb.Y-QJb.Y*TJb,UJb.Z-QJb.Z*TJb
KJb.bx,KJb.by,KJb.bz=UJb.X+QJb.X*TJb,UJb.Y+QJb.Y*TJb,UJb.Z+QJb.Z*TJb
KJb.len=MJb.X
if math.abs(QJb.Y)<0.05 and math.abs(UJb.Y-(JJb.floor+1.15))<0.6 then
if math.abs(MJb.X-46)<1 then
KJb.r=QHb.R_BEAM
KJb.ang=math.atan2(KJb.bz-KJb.az,KJb.bx-KJb.ax)
return EQd[1551]
end
KJb.r=QHb.R_FAN
return EQd[1555]
end
if SJb<=0.2 then
KJb.r=QHb.R_CLONE
return EQd[1553]
end
if SJb<=0.25 then
KJb.r=QHb.R_SHOT
return EQd[1552]
end
return nil
elseif OJb==QHb.BLOCK then
if not PJb then
return nil
end
if MJb.Y<=0.26 and math.abs(NJb.UpVector.Y)>0.9 then
local VJb=NJb.RightVector
local WJb=math.sqrt(VJb.X*VJb.X+VJb.Z*VJb.Z)
if WJb<0.5 then
return nil
end
KJb.x,KJb.z=NJb.X,NJb.Z
KJb.ux,KJb.uz=VJb.X/WJb,VJb.Z/WJb
KJb.hl,KJb.hw=MJb.X/2+QHb.SAW_END,math.max(QHb.SAW_SIDE,MJb.Z/2)
return EQd[443]
end
if MJb.X<=0.26 and MJb.Y>40 and MJb.Z>40 then
return EQd[1556]
end
end
return nil
end
function QHb.copy(XJb,YJb)
XJb.kind,XJb.x,XJb.z,XJb.r,XJb.len,XJb.ang=YJb.kind,YJb.x,YJb.z,YJb.r,YJb.len,YJb.ang
XJb.ax,XJb.ay,XJb.az,XJb.bx,XJb.by,XJb.bz=YJb.ax,YJb.ay,YJb.az,YJb.bx,YJb.by,YJb.bz
XJb.ux,XJb.uz,XJb.hl,XJb.hw=YJb.ux,YJb.uz,YJb.hl,YJb.hw
return XJb
end
function QHb.scan(ZJb,_Jb,aKb,bKb)
local cKb,dKb=aKb.cur,aKb.pool
table.clear(cKb)
table.clear(aKb.lights)
aKb.plate=false
local eKb=0
for fKb,gKb in ipairs(_Jb)do
if gKb.ClassName==EQd[546]then
local hKb=dKb[eKb+1]
if not hKb then
hKb={}
dKb[eKb+1]=hKb
end
local iKb=QHb.classify(gKb,ZJb,hKb)
if iKb==EQd[1556]then
aKb.plate=true
aKb.seen.plate=bKb
elseif iKb==EQd[1590]then
aKb.lights[#aKb.lights+1]=gKb.Position
elseif iKb then
local jKb=aKb.mem[gKb]
if iKb==EQd[1437]and jKb and jKb.s.kind==EQd[1437]and(math.abs(jKb.s.x-hKb.x)>0.05 or math.abs(jKb.s.z-hKb.z)>0.05)then
jKb.moving=true
end
if not jKb then
jKb={s={}}
aKb.mem[gKb]=jKb
end
if not jKb.moving then
eKb=eKb+1
hKb.kind=iKb
cKb[eKb]=hKb
aKb.seen[iKb]=bKb
QHb.copy(jKb.s,hKb)
end
jKb.t=bKb
end
end
end
local kKb=aKb.memList
table.clear(kKb)
for lKb,mKb in pairs(aKb.mem)do
if bKb-mKb.t>(QHb.LINGER[mKb.s.kind]or 0.3)then
aKb.mem[lKb]=nil
elseif mKb.t<bKb and not mKb.moving then
kKb[#kKb+1]=mKb.s
end
end
end
function QHb.capAt(nKb,oKb,pKb,qKb,rKb,sKb)
local tKb=nKb.caps[oKb]
if not tKb then
tKb={kind=EQd[1591],r=QHb.SAW_SIDE}
nKb.caps[oKb]=tKb
end
tKb.ax,tKb.az,tKb.bx,tKb.bz=pKb,qKb,rKb,sKb
end
function QHb.caps(uKb)
local vKb=uKb.chainList
table.clear(vKb)
for wKb,xKb in ipairs(uKb.cur)do
if xKb.kind==EQd[1554]then
vKb[#vKb+1]=xKb
end
end
for yKb,zKb in ipairs(uKb.memList)do
if zKb.kind==EQd[1554]then
vKb[#vKb+1]=zKb
end
end
local AKb=0
if#vKb>=2 then
for BKb,CKb in ipairs(vKb)do
local DKb,EKb,FKb,GKb=nil,math.huge,nil,math.huge
for HKb,IKb in ipairs(vKb)do
if HKb~=BKb then
local JKb,KKb=IKb.x-CKb.x,IKb.z-CKb.z
local LKb=JKb*JKb+KKb*KKb
if LKb>0.01 and LKb<196 then
if LKb<EKb then
FKb,GKb,DKb,EKb=DKb,EKb,IKb,LKb
elseif LKb<GKb then
FKb,GKb=IKb,LKb
end
end
end
end
if DKb then
AKb=AKb+1
QHb.capAt(uKb,AKb,CKb.x,CKb.z,DKb.x,DKb.z)
local MKb,NKb=CKb.x-DKb.x,CKb.z-DKb.z
if FKb then
AKb=AKb+1
QHb.capAt(uKb,AKb,CKb.x,CKb.z,FKb.x,FKb.z)
if(DKb.x-CKb.x)*(FKb.x-CKb.x)+(DKb.z-CKb.z)*(FKb.z-CKb.z)<0 then
MKb,NKb=FKb.x-DKb.x,FKb.z-DKb.z
end
end
local OKb=math.sqrt(MKb*MKb+NKb*NKb)
if OKb>0.01 then
MKb,NKb=MKb/OKb*QHb.SAW_END,NKb/OKb*QHb.SAW_END
AKb=AKb+1
QHb.capAt(uKb,AKb,CKb.x-MKb,CKb.z-NKb,CKb.x+MKb,CKb.z+NKb)
end
end
end
end
uKb.capN=AKb
end
function QHb.segFlat(PKb,QKb,RKb)
local SKb,TKb=PKb.bx-PKb.ax,PKb.bz-PKb.az
local UKb,VKb=QKb-PKb.ax,RKb-PKb.az
local WKb=SKb*SKb+TKb*TKb
local XKb=WKb>1e-6 and math.clamp((UKb*SKb+VKb*TKb)/WKb,0,1)or 0
local YKb,ZKb=UKb-SKb*XKb,VKb-TKb*XKb
return math.sqrt(YKb*YKb+ZKb*ZKb)
end
function QHb.seg3(_Kb,aLb,bLb,cLb)
local dLb,eLb,fLb=_Kb.bx-_Kb.ax,_Kb.by-_Kb.ay,_Kb.bz-_Kb.az
local gLb,hLb,iLb=aLb-_Kb.ax,bLb-_Kb.ay,cLb-_Kb.az
local jLb=dLb*dLb+eLb*eLb+fLb*fLb
local kLb=jLb>1e-6 and math.clamp((gLb*dLb+hLb*eLb+iLb*fLb)/jLb,0,1)or 0
local lLb,mLb,nLb=gLb-dLb*kLb,hLb-eLb*kLb,iLb-fLb*kLb
return math.sqrt(lLb*lLb+mLb*mLb+nLb*nLb)
end
function QHb.spinGap(oLb,pLb,qLb)
local rLb=math.abs(QHb.wrap(math.atan2(qLb-oLb.az,pLb-oLb.ax)-oLb.ang))
if rLb>math.pi/2 then
rLb=math.pi-rLb
end
return rLb
end
function QHb.hit(sLb,tLb,uLb,vLb,wLb,xLb)
local yLb=sLb.kind
if yLb==EQd[1437]then
local zLb,ALb=tLb-sLb.x,vLb-sLb.z
local BLb=sLb.r+wLb
return zLb*zLb+ALb*ALb<=BLb*BLb
elseif yLb==EQd[1554]then
local CLb,DLb=tLb-sLb.x,vLb-sLb.z
local ELb=QHb.SAW_SIDE+wLb
return CLb*CLb+DLb*DLb<=ELb*ELb
elseif yLb==EQd[443]then
local FLb,GLb=tLb-sLb.x,vLb-sLb.z
local HLb=FLb*sLb.ux+GLb*sLb.uz
local ILb=GLb*sLb.ux-FLb*sLb.uz
return math.abs(HLb)<=sLb.hl+wLb and math.abs(ILb)<=sLb.hw+wLb
elseif yLb==EQd[1555]or yLb==EQd[1591]then
return QHb.segFlat(sLb,tLb,vLb)<=sLb.r+wLb
elseif yLb==EQd[1552]or yLb==EQd[1553]then
return QHb.seg3(sLb,tLb,uLb,vLb)<=sLb.r+wLb
elseif yLb==EQd[1551]then
local JLb,KLb=tLb-sLb.ax,vLb-sLb.az
local LLb=math.sqrt(JLb*JLb+KLb*KLb)
local MLb=sLb.r+wLb
if LLb<=MLb then
return true
end
if LLb>sLb.len+MLb then
return false
end
return QHb.spinGap(sLb,tLb,vLb)<math.asin(MLb/LLb)+QHb.SPIN_W*(xLb or 0)
end
return false
end
function QHb.safe(NLb,OLb,PLb,QLb,RLb,SLb)
for TLb,ULb in ipairs(NLb.cur)do
if QHb.hit(ULb,OLb,PLb,QLb,RLb,SLb)then
return false
end
end
for VLb,WLb in ipairs(NLb.memList)do
if QHb.hit(WLb,OLb,PLb,QLb,RLb,SLb)then
return false
end
end
for XLb=1,NLb.capN do
if QHb.hit(NLb.caps[XLb],OLb,PLb,QLb,RLb,SLb)then
return false
end
end
return true
end
function QHb.pickTry(YLb,ZLb,_Lb)
if not QHb.inBox(YLb.A,ZLb,_Lb,QHb.EDGE)then
return
end
local aMb=YLb.eye
local bMb
if aMb then
local cMb,dMb=ZLb-aMb.X,_Lb-aMb.Z
bMb=math.sqrt(cMb*cMb+dMb*dMb)
if bMb<QHb.PUSH then
return
end
end
local eMb=YLb.st
if not QHb.safe(eMb,ZLb,YLb.y,_Lb,YLb.m,QHb.LEAD_PICK)then
return
end
local fMb,gMb=ZLb-YLb.px,_Lb-YLb.pz
local hMb=math.sqrt(fMb*fMb+gMb*gMb)
local iMb=true
if bMb then
iMb=bMb<=QHb.REACH
if not iMb then
hMb=hMb+1000+bMb
end
hMb=hMb+math.abs(bMb-QHb.STAND)*0.5
end
for jMb,kMb in ipairs(eMb.cur)do
if kMb.kind==EQd[1551]then
hMb=hMb+(math.pi/2-QHb.spinGap(kMb,ZLb,_Lb))*4
end
end
if not YLb.score or hMb<YLb.score then
YLb.bx,YLb.bz,YLb.score,YLb.inR=ZLb,_Lb,hMb,iMb
end
end
function QHb.pick(lMb,mMb,nMb,oMb,pMb,qMb)
local rMb=QHb.S
rMb.A,rMb.st,rMb.eye,rMb.m,rMb.y,rMb.px,rMb.pz=lMb,mMb,nMb,pMb,qMb,oMb.X,oMb.Z
rMb.score,rMb.bx,rMb.bz,rMb.inR=nil,nil,nil,nil
local sMb=QHb.unit(QHb.ANGLES)
if nMb then
for tMb,uMb in ipairs(QHb.RINGS)do
for vMb,wMb in ipairs(sMb)do
QHb.pickTry(rMb,nMb.X+wMb[1]*uMb,nMb.Z+wMb[2]*uMb)
end
end
end
if not rMb.score or not rMb.inR then
local xMb=lMb.centre
for yMb,zMb in ipairs(QHb.WIDE)do
if zMb==0 then
QHb.pickTry(rMb,xMb.X,xMb.Z)
else
for AMb,BMb in ipairs(sMb)do
QHb.pickTry(rMb,xMb.X+BMb[1]*zMb,xMb.Z+BMb[2]*zMb)
end
end
end
end
rMb.A,rMb.st,rMb.eye=nil,nil,nil
if not rMb.score then
return nil,false
end
return Vector3 .new(rMb.bx,lMb.floor,rMb.bz),rMb.inR
end
function QHb.place(CMb,DMb,EMb,FMb,GMb)
local HMb=cb.Character
if not(HMb and GMb)then
return false
end
local IMb=DMb.floor+QHb.rootH(GMb,FMb)+0.2
local JMb=os.clock()-(QHb.jumpAt or-1e9)<0.7 or(FMb~=nil and FMb.FloorMaterial==Enum.Material.Air)
if JMb and GMb.Position.Y>DMb.floor+0.5 and GMb.Position.Y<DMb.floor+25 then
IMb=GMb.Position.Y
end
local KMb=Vector3 .new(CMb.X,IMb,CMb.Z)
local LMb=CFrame.new(KMb)
if EMb then
local MMb=Vector3 .new(EMb.X,IMb,EMb.Z)
if(MMb-KMb).Magnitude>0.5 then
LMb=CFrame.lookAt(KMb,MMb)
end
end
if not JMb then
GMb.AssemblyLinearVelocity=Vector3 .zero
end
return(pcall(HMb.PivotTo,HMb,LMb))
end
function QHb.jump(NMb,OMb)
local PMb=os.clock()
if not NMb or PMb-(QHb.jumpAt or-1e9)<0.3 then
return
end
if NMb.FloorMaterial==Enum.Material.Air then
return
end
QHb.jumpAt=PMb
OMb.jumps=(OMb.jumps or 0)+1
pcall(NMb.ChangeState,NMb,Enum.HumanoidStateType.Jumping)
end
function QHb.spinJump(QMb,RMb,SMb,TMb,UMb)
if RMb.Y-UMb.floor>=4.6 then
return
end
for VMb,WMb in ipairs(QMb.cur)do
if WMb.kind==EQd[1551]then
local XMb,YMb=RMb.X-WMb.ax,RMb.Z-WMb.az
local ZMb=math.sqrt(XMb*XMb+YMb*YMb)
if ZMb>QHb.R_BEAM and ZMb<=WMb.len+QHb.R_BEAM and QHb.spinGap(WMb,RMb.X,RMb.Z)<math.asin(QHb.R_BEAM/ZMb)+QHb.SPIN_W*0.12 then
QHb.jump(SMb,TMb)
return
end
end
end
end
function QHb.watchFx(_Mb)
local aNb=workspace:FindFirstChild(EQd[1579])
if aNb==_Mb.fx and _Mb.kids then
return _Mb.kids
end
QHb.unwatchFx(_Mb)
local bNb,cNb={},{}
local dNb,eNb,fNb={},0,0
_Mb.fx,_Mb.kids,_Mb.fxGone=aNb,bNb,dNb
if not aNb then
return bNb
end
local gNb,hNb=pcall(aNb.GetChildren,aNb)
if gNb then
for iNb,jNb in ipairs(hNb)do
bNb[#bNb+1]=jNb
cNb[jNb]= #bNb
end
end
_Mb.fxConns={aNb.ChildAdded:Connect(function(kNb)
if cNb[kNb]then
return
end
bNb[#bNb+1]=kNb
cNb[kNb]= #bNb
end),aNb.ChildRemoved:Connect(function(lNb)
local mNb=os.clock()
dNb[lNb]=mNb
eNb=eNb+1
if eNb>120 and mNb-fNb>0.5 then
eNb,fNb=0,mNb
for nNb,oNb in pairs(dNb)do
if mNb-oNb>2 then
dNb[nNb]=nil
else
eNb=eNb+1
end
end
end
local pNb=cNb[lNb]
if not pNb then
return
end
local qNb= #bNb
local rNb=bNb[qNb]
bNb[pNb],cNb[rNb]=rNb,pNb
bNb[qNb],cNb[lNb]=nil,nil
end)}
return bNb
end
function QHb.unwatchFx(sNb)
if type(sNb)~=EQd[106]then
return
end
for tNb,uNb in ipairs(sNb.fxConns or QHb.EMPTY)do
pcall(uNb.Disconnect,uNb)
end
sNb.fxConns,sNb.fx,sNb.kids,sNb.fxGone=nil,nil,nil,nil
end
function QHb.step(vNb,wNb)
local xNb,yNb=jb.root()
if not xNb then
return
end
local zNb=xNb.Position
local ANb=os.clock()
local BNb,CNb=QHb.loc(vNb,zNb.X,zNb.Z)
if(math.abs(BNb)>QHb.HALF+20 or math.abs(CNb)>QHb.HALF+20 or math.abs(zNb.Y-vNb.floor)>40)and ANb-(wNb.streamAt or-1e9)>3 then
wNb.streamAt=ANb
pcall(cb.RequestStreamAroundAsync,cb,vNb.centre,2)
xNb,yNb=jb.root()
if not xNb then
return
end
zNb=xNb.Position
