function QHb.openGate()
if jb.has(EQd[1691])then
return true
end
if not jb.has(EQd[1599])then
return false
end
QHb.waitFor(function()
return not jb.has(EQd[203])
end,6)
if not F.alive or F.yielding()then
return false
end
local iTb=QHb.lock()
if not iTb then
local jTb=QHb.geo()
if jTb then
pcall(cb.RequestStreamAroundAsync,cb,jTb.centre,2)
end
iTb=QHb.lock()
end
local kTb=iTb and iTb:FindFirstChildOfClass(EQd[331])
if iTb then
mb.to(iTb.Position)
task.wait(0.6)
if not F.alive then
return false
end
end
if kTb and fireproximityprompt then
pcall(fireproximityprompt,kTb,kTb.HoldDuration)
end
local lTb=QHb.waitFor(function()
return jb.has(EQd[1691])
end,1.5)
if not lTb and F.alive and not jb.has(EQd[1691])then
jb.fire(EQd[633],QHb.BID)
end
lTb=lTb or QHb.waitFor(function()
return jb.has(EQd[1691])
end,4)
nb.back=true
if lTb then
F.note(EQd[309],EQd[1692]..QHb.openWords())
return true
end
F.log(1,EQd[1597],EQd[1693]..tostring(iTb~=nil)..EQd[1694]..tostring(kTb~=nil)..EQd[289])
return false
end
function QHb.fight()
QHb.res,QHb.stopWhy=nil,nil
if eb.master==false or eb.boss==false or not eb[EQd[187]..QHb.id]then
QHb.stopWhy=EQd[625]
return false
end
local mTb=QHb.isEcho()
if not F.alive then
return false
end
if F.yielding()then
QHb.stopWhy=EQd[574]
return false
end
if jb.busy()then
QHb.stopWhy=EQd[722]
return false
end
local nTb=QHb.geo()
if not nTb then
if not(QHb.room()or workspace:FindFirstChild(EQd[346]))then
if mTb then
QHb.startFail(EQd[1695])
else
QHb.backUntil,QHb.backWhy=os.clock()+300,EQd[1695]
QHb.stopWhy=EQd[572]
end
return false
end
local oTb=QHb.stairPos()
if oTb then
mb.to(oTb)
end
nTb=QHb.waitFor(QHb.geo,4)
if not F.alive then
return false
end
if not nTb and not F.yielding()then
jb.fire(EQd[1501],EQd[1575])
nTb=QHb.waitFor(QHb.geo,5)
if not F.alive then
return false
end
end
if not nTb then
QHb.startFail(EQd[1696])
return false
end
QHb.waitFor(function()
return not jb.busy()
end,3)
if not F.alive then
return false
end
if F.yielding()then
QHb.stopShort(mTb,EQd[574],30,EQd[1503])
return false
end
if jb.busy()then
QHb.stopShort(mTb,EQd[722],60,EQd[1504])
return false
end
end
QHb.hook()
QHb.res,QHb.live=nil,{}
QHb.prevBossId,qb.id,QHb.guard=qb.id,QHb.BID,true
local pTb=QHb.newCtx()
pTb.echo=mTb
pTb.echoMS=mTb and jb.n(EQd[1664])or nil
if mTb then
pTb.dh.mode=QHb.echoMode()
pTb.trial=false
end
QHb.ctx=pTb
if mTb then
local qTb=QHb.echoHits()
F.now={icon=QHb.icon,title=EQd[1697],text=qTb and string.format(EQd[1698],qTb)or EQd[1699],sub=EQd[146]}
else
F.now={icon=QHb.icon,title=EQd[1700],text=EQd[1701]..(select(2,QHb.prize())),sub=EQd[146]}
end
mb.to(nTb.centre)
task.spawn(function()
pcall(cb.RequestStreamAroundAsync,cb,nTb.centre,3)
end)
local rTb=QHb.learn()
rTb.startedAt,rTb.autoWas=os.time(),cb:GetAttribute(EQd[376])==true
rTb.mode,rTb.dmg,rTb.activeAt,rTb.deadline=pTb.dh.mode or EQd[146],nil,nil,nil
rTb.echo,rTb.echoMS=mTb==true,pTb.echoMS
F.saveSoon()
QHb.arriveAt,QHb.lastSettle=os.clock(),nil
local sTb=QHb.fails()
local tTb=1.5*2^math.min(2,(sTb and sTb.why==EQd[572]and tonumber(sTb.n))or 0)
local uTb,vTb,wTb=QHb.pressBox(nTb,tTb,false)
if wTb==EQd[573]then
return false
end
local xTb=wTb==EQd[1636]
if not uTb and wTb~=EQd[574]and not F.yielding()and not jb.has(EQd[203])then
local yTb,zTb,ATb=QHb.pressBox(nTb,tTb,true)
if ATb==EQd[573]then
return false
end
uTb,vTb,wTb=yTb,vTb or zTb,ATb
xTb=xTb or ATb==EQd[1636]
end
if wTb==EQd[574]then
QHb.stopShort(mTb,EQd[574],30,EQd[1503])
return false
end
local BTb,CTb=uTb==EQd[400]and 1 or 0,false
while BTb>0 and F.alive do
local DTb=QHb.waitFor(function()
return jb.has(EQd[203])or QHb.live.intro
end,3)
if not F.alive then
