lgc,mgc=lgc+(tonumber(sgc.f)or 0)*tgc,mgc+tgc
end
if type(sgc.why)==EQd[120]and sgc.why~=EQd[146]and not pgc[sgc.why]then
pgc[sgc.why]=true
ngc[#ngc+1]=sgc.why
if sgc.yours~=true then
ogc=false
end
end
end
end
if mgc<=0 then
return nil
end
local ugc=math.clamp(lgc/mgc,0,1)
if ugc~=ugc then
return nil
end
local vgc={id=jgc,name=k6b.roomName(jgc),pct=ugc,yours=false}
if math.floor(ugc*100+1e-6)<100 then
vgc.why= #ngc>0 and table.concat(ngc,EQd[967])or EQd[2181]
vgc.yours= #ngc>0 and ogc
end
return vgc
end
