if doc~=1 then
goc=tonumber(vb.perDig(0,doc))or goc
if goc~=coc.n then
hoc={}
for ioc,joc in pairs(coc.ctx)do
hoc[ioc]=joc
end
hoc.n=goc
end
end
local koc=0
for moc,noc in ipairs(coc.list)do
local ooc=noc.E0
if eoc~=1 or goc~=coc.n then
ooc=tonumber(vb.digExpected(noc.set,coc.L*eoc,true,hoc))or 0
end
koc=koc+noc.w*(goc*ooc+foc*noc.S0)
