return PLc.treeCache
end
function PLc.buyable(KPc)
if type(KPc)~=EQd[106]or not KPc.id or jb.has(EQd[268]..KPc.id)then
return false
end
if KPc.soon or KPc.world==2 or(KPc.currency or EQd[175])==EQd[248]or not tonumber(KPc.cost)then
return false
end
if jb.n(EQd[98])<(tonumber(KPc.rebirth)or 0)then
return false
end
local LPc=jb.PC
local MPc=LPc and LPc.TreeRoomIds and LPc.TreeRoomIds[KPc.tree or 1]
return not MPc or jb.roomOwned(MPc)
end
function PLc.nodeOpen(NPc,OPc)
