end
return ZPc
end
function PLc.applyNode(bQc,cQc)
local dQc=bQc[cQc.stat]
if dQc==nil then
dQc=tonumber(jb.a(cQc.stat))or PLc.TREE_DEF[cQc.stat]or(cQc.op==EQd[269]and 1 or 0)
end
if cQc.op==EQd[269]then
bQc[cQc.stat]=dQc*(tonumber(cQc.value)or 1)
else
bQc[cQc.stat]=dQc+(tonumber(cQc.value)or 0)
end
end
function PLc.chain(eQc,fQc,gQc,hQc,iQc,jQc)
local kQc=PLc.treeMaps()
local lQc=eQc.currency or EQd[175]
local mQc
local function nQc(oQc,pQc,qQc)
local rQc=(PLc.call(hQc,oQc)or 0)-gQc
if pQc>0 and rQc>0 and(not mQc or rQc/pQc>mQc.ratio)then
mQc={ratio=rQc/pQc,dR=rQc,cost=pQc,over=oQc,chain=qQc}
end
end
local function sQc(tQc)
return PLc.statOf(tQc,iQc)and(tQc.currency or EQd[175])==lQc and PLc.buyable(tQc)and not(jQc and jQc[tQc.id])
end
local uQc=PLc.copy(fQc)
PLc.applyNode(uQc,eQc)
local vQc=tonumber(eQc.cost)or 0
nQc(uQc,vQc,{eQc})
for wQc,xQc in ipairs(kQc.kids[eQc.id]or{})do
if sQc(xQc)then
local yQc=PLc.copy(uQc)
PLc.applyNode(yQc,xQc)
local zQc=vQc+(tonumber(xQc.cost)or 0)
nQc(yQc,zQc,{eQc,xQc})
for AQc,BQc in ipairs(kQc.kids[xQc.id]or{})do
if sQc(BQc)then
local CQc=PLc.copy(yQc)
PLc.applyNode(CQc,BQc)
nQc(CQc,zQc+(tonumber(BQc.cost)or 0),{eQc,xQc,BQc})
end
end
end
end
return mQc
end
function PLc.model()
local DQc=PLc.spots()
local EQc=PLc.grow()
