local GQc=1
if not PLc.autoOn()then
GQc=PLc.share(#DQc,EQc)
if FQc>0 and(PLc.unknownPots or 0)>0 then
GQc=GQc*(FQc-PLc.unknownPots)/FQc
end
end
return{R=PLc.rate(),share=GQc,K= #DQc,grow=EQc,n=FQc,spm=PLc.call(EQd[2686])or 1,spots=DQc}
end
function PLc.collect(HQc)
local IQc=PLc.measured(EQd[278])
if IQc>0 then
return IQc
end
return HQc.R*HQc.share
