function PLc.kingNeed()
local SQc=jb.PC and jb.PC.Boss and jb.PC.Boss.MushroomKing
if type(SQc)~=EQd[106]then
return nil,nil
end
local TQc
if type(qb.bar)==EQd[188]then
local UQc,VQc=pcall(qb.bar,SQc,EQd[2120])
TQc=UQc and tonumber(VQc)or nil
end
if not TQc or TQc~=TQc or TQc<=0 or TQc==math.huge then
TQc=(tonumber(SQc.hp)or 43e6)/((tonumber(SQc.time)or 100)/(tonumber(SQc.swing)or 0.35))
end
return TQc,SQc
end
function PLc.planTo(WQc)
local XQc=jb.PC
local YQc=PLc.treeMaps()
local ZQc,_Qc={},{}
for aRc,bRc in ipairs(PLc.UPS)do
ZQc[EQd[247]..bRc]=jb.n(EQd[247]..bRc)
end
local cRc,dRc,eRc=PLc.rate(ZQc),0,0
for fRc=1,100 do
if cRc>=WQc then
break
end
local gRc
for hRc,iRc in ipairs(PLc.UPS)do
local jRc=XQc.Upgrades and XQc.Upgrades[iRc]
local kRc=ZQc[EQd[247]..iRc]
if jRc and kRc<(tonumber(jRc.max)or 0)then
local lRc,mRc=pcall(XQc.UpgradeCost,iRc,kRc)
mRc=lRc and tonumber(mRc)or nil
if mRc and mRc>=0 then
local nRc=PLc.free(iRc)
local oRc=PLc.copy(ZQc)
oRc[EQd[247]..iRc]=kRc+1
local pRc=PLc.rate(oRc)-cRc
local qRc=(nRc or mRc<=0)and 1e300/math.max(mRc,1)or pRc/mRc
if pRc>0 and(not gRc or qRc>gRc.ratio)then
gRc={ratio=qRc,cost=nRc and 0 or mRc,over=oRc,price=nRc and mRc or nil}
end
end
end
end
for rRc,sRc in ipairs(YQc.list)do
if PLc.statOf(sRc,PLc.TREE)and sRc.currency==EQd[278]and not _Qc[sRc.id]and PLc.nodeOpen(sRc,_Qc)then
local tRc=PLc.chain(sRc,ZQc,cRc,EQd[403],PLc.TREE,_Qc)
if tRc and(not gRc or tRc.ratio>gRc.ratio)then
gRc=tRc
end
end
end
if not gRc then
break
end
ZQc,dRc=gRc.over,dRc+gRc.cost
if gRc.price and gRc.price>eRc then
eRc=gRc.price
end
for uRc,vRc in ipairs(gRc.chain or{})do
_Qc[vRc.id]=true
end
cRc=PLc.rate(ZQc)
end
return dRc,cRc,eRc
end
function PLc.gateCur(wRc)
for xRc,yRc in ipairs(type(wRc.opts)==EQd[106]and wRc.opts or{})do
