function PLc.pastKing(ORc)
local PRc=jb.PC
local QRc=tonumber(ORc.step)or 821
local RRc=math.huge
for SRc,TRc in ipairs(PRc.StepGates or{})do
local URc=type(TRc)==EQd[106]and tonumber(TRc.step)
if URc and URc>QRc and URc<RRc then
RRc=URc
end
end
local VRc=tonumber(db.ROOM_GAIN)or 1
local WRc=0
for XRc,YRc in ipairs(PRc.Rooms or{})do
local ZRc=type(YRc)==EQd[106]and tonumber(YRc.step)
if ZRc and ZRc>=QRc and ZRc<RRc and YRc.world~=2 and YRc.currency~=EQd[248]and not jb.roomOwned(YRc.id)then
WRc=WRc+VRc
