function PLc.kingPlan(_Rc)
local aSc=os.clock()
if PLc.kingCache and aSc-PLc.kingCache.at<5 and PLc.kingCache.need==_Rc then
return PLc.kingCache.cost
end
local bSc=0
if PLc.rate()<_Rc then
local cSc,dSc,eSc=PLc.planTo(_Rc)
cSc,eSc=tonumber(cSc)or 0,tonumber(eSc)or 0
if cSc>0 or eSc>0 then
bSc=math.max(cSc,eSc,1)
end
end
PLc.kingCache={at=aSc,need=_Rc,cost=bSc}
