end
function PLc.kingHeld()
local BSc=type(gb.bossFails)==EQd[106]and gb.bossFails.MushroomKing or nil
if type(BSc)==EQd[106]and tonumber(BSc.untilT)and BSc.untilT>os.time()then
return true
end
return qb.backUntil~=nil and os.clock()<qb.backUntil
