function PLc.keptKing()
local CSc=PLc.kingAhead()
if not CSc then
return nil
end
local DSc,ESc=PLc.rate(),(tonumber(db.HORIZON)or 300)
local FSc=0.05*CSc*ESc*0.5
local GSc
if DSc<CSc then
GSc=math.max(CSc-DSc,0.05*CSc)*ESc*0.5
OLc.stats._kingCost=GSc
else
if not PLc.kingHeld()then
return nil
end
GSc=tonumber(OLc.stats._kingCost)or 0
if GSc>0 then
GSc=math.max(GSc,FSc)
end
end
if not(GSc>0)then
return nil
end
return{kind=EQd[2691],kept=true,cost=GSc,need=CSc,mult=PLc.kingMult(),name=EQd[463]}
end
function PLc.readGoal()
