end
function PLc.realK(KSc)
local LSc=kb.last
if type(LSc)~=EQd[106]then
return 0,nil
end
PLc.realCache=(PLc.realCache and PLc.realCache.at==LSc.at)and PLc.realCache or{at=LSc.at}
local MSc=PLc.realCache[KSc]
if MSc then
return MSc.k,MSc.row
end
local NSc,OSc=0,nil
for PSc,QSc in ipairs(type(LSc.opts)==EQd[106]and LSc.opts or{})do
local RSc,SSc=type(QSc)==EQd[106]and tonumber(QSc.cost),type(QSc)==EQd[106]and tonumber(QSc.gain)
if RSc and SSc and QSc.cur==KSc and not QSc.accel and not QSc.est and RSc>0 and SSc>0 and SSc/RSc>NSc then
NSc,OSc=SSc/RSc,QSc
