function PLc.readPrice(ZSc,_Sc)
if not(ZSc and ZSc.cost>0)then
return 0
end
local aTc=(tonumber(_Sc)or 0)*ZSc.mult
if ZSc.kept then
return aTc/ZSc.cost
end
local bTc=math.max(0,ZSc.cost-jb.n(EQd[278]))
if bTc<=0 then
return 0
end
local cTc=aTc/ZSc.cost
local dTc=PLc.collect(PLc.model())
local eTc=tonumber(db.HORIZON)or 300
if not(dTc>0)or dTc*eTc<bTc then
return cTc
end
return math.min(cTc,aTc*bTc/(dTc*dTc*eTc*eTc*0.5))
end
function OLc.worthFloor(fTc)
