for vTc,wTc in ipairs(ub.list)do
if wTc~=OLc and ub.on(wTc.id)then
if type(wTc.worthFloor)==EQd[188]then
local xTc,yTc=pcall(wTc.worthFloor,EQd[279])
yTc=xTc and tonumber(yTc)or 0
if yTc==yTc and yTc>rTc then
rTc=yTc
end
end
if type(wTc.worthCap)==EQd[188]then
local zTc,ATc=pcall(wTc.worthCap,EQd[279])
