local NTc=tonumber(MTc.value)or 0
if NTc==NTc and NTc>KTc then
KTc=NTc
end
end
end
for OTc,PTc in ipairs(type(vb.digOpts)==EQd[106]and vb.digOpts or{})do
local QTc=type(PTc)==EQd[106]and tonumber(PTc.value)or 0
if QTc==QTc and QTc>KTc then
KTc=QTc
end
