for UTc,VTc in ipairs(TTc)do
if type(VTc)==EQd[106]and VTc.boss==true and VTc.sys~=OLc.id then
local WTc=tonumber(VTc.value)or 0
if WTc==WTc and WTc>STc then
RTc=math.min(RTc,math.max(WTc*0.8,STc))
