function PLc.pivot(XTc)
local YTc,ZTc=cb.Character,jb.root()
if not(YTc and ZTc)or PLc.locked()then
return false
end
return(pcall(function()
ZTc.AssemblyLinearVelocity=Vector3 .zero
YTc:PivotTo(CFrame.new(XTc)*ZTc.CFrame.Rotation)
