function PLc.goTo(_Tc)
local aUc=jb.root()
if not aUc or PLc.locked()then
return false
end
local bUc=PLc.standAt(_Tc)
local cUc=(aUc.Position-bUc).Magnitude>80
local dUc
if type(vb.hop)==EQd[188]and vb.loopOn and eb.v2presence~=false then
dUc=vb.hop(bUc,not cUc)
else
if cUc then
