end
end
end
function PLc.shrink(mUc,nUc)
local oUc=(OLc.stats._provenRange==PLc.range())and tonumber(OLc.stats._proven)or 0
mUc=math.max(3,mUc,oUc+0.1)
local pUc=PLc.capNow()
if pUc and pUc<=mUc then
return
end
if mUc>=PLc.range()-PLc.MARGIN then
return
end
OLc.stats._reachCap,OLc.stats._capRange,OLc.stats._capAt=mUc,PLc.range(),os.time()
F.log(1,EQd[2681],string.format(EQd[2692],nUc,mUc))
