local vUc=(OLc.stats._provenRange==PLc.range())and tonumber(OLc.stats._proven)or 0
local wUc=false
for xUc,yUc in ipairs(qUc.pots)do
if(PLc.harvAt[yUc]or 0)>=(PLc.arrive or 0)then
wUc=true
end
end
local zUc=false
for AUc,BUc in ipairs(rUc)do
local CUc=PLc.pots[BUc.i]
if not BUc.unknown and CUc then
zUc=true
local DUc=(sUc.Position-CUc).Magnitude
local EUc=os.clock()+(BUc.left or 0)
local FUc=false
for GUc,HUc in ipairs(qUc.pots)do
local IUc=PLc.pots[HUc]
if HUc~=BUc.i and IUc and(PLc.harvAt[HUc]or 0)>=math.max(EUc,PLc.arrive or 0)+0.1 and(sUc.Position-IUc).Magnitude+0.25<DUc then
FUc=true
end
end
if FUc and DUc>vUc+0.25 then
PLc.strikes[BUc.i]=(PLc.strikes[BUc.i]or 0)+1
if PLc.strikes[BUc.i]>=2 then
PLc.strikes[BUc.i]=nil
PLc.shrink(DUc-0.5,string.format(EQd[2693],BUc.i,DUc))
end
end
if not wUc and DUc>vUc+0.25 then
PLc.dryD=math.max(PLc.dryD or 0,DUc)
end
end
uUc.pots[BUc.i]={t=tUc,glow=false,guess=true}
end
if not zUc then
return
end
PLc.ask(true)
if not wUc and PLc.dryD then
PLc.dry=(PLc.dry or 0)+1
if PLc.dry>=3 then
PLc.shrink(PLc.dryD-1,EQd[2694])
PLc.dry,PLc.dryD=0,nil
end
end
end
function PLc.learnDy(JUc,KUc,LUc)
