if OUc> -1 and OUc<6 then
local PUc=tonumber(OLc.stats._dy)or OUc
OLc.stats._dy=PUc+(OUc-PUc)*0.3
end
end
function PLc.run(QUc,RUc)
RUc=tonumber(RUc)or 30
local SUc=os.clock()
local TUc,UUc=0,nil
local VUc=PLc.confWait()
OLc.working=true
PLc.beat=SUc
while F.alive and os.clock()-SUc<RUc-0.1 do
if PLc.locked()or jb.busy()or PLc.autoOn()then
break
end
local WUc,XUc=jb.root()
if not WUc or PLc.inWorld2(WUc.Position)then
break
end
local YUc=PLc.spots()
if#YUc==0 then
break
end
local ZUc,_Uc=PLc.serverNow(),PLc.grow()
local aVc=PLc.spotAt(WUc.Position,YUc,UUc or PLc.cur)
if aVc~=UUc then
UUc=aVc
if aVc and PLc.cur~=aVc then
PLc.arrived(aVc)
if type(QUc)==EQd[106]and tonumber(QUc.arrivedAt)and os.clock()-QUc.arrivedAt<3 then
PLc.arrive=QUc.arrivedAt
end
end
PLc.cur=aVc
end
if UUc and XUc then
PLc.learnDy(UUc,WUc,XUc)
end
local bVc,cVc=false,{}
if UUc then
local dVc=os.clock()-(PLc.arrive or os.clock())
for eVc,fVc in ipairs(UUc.pots)do
local gVc,hVc,iVc=PLc.left(fVc,ZUc,_Uc)
if gVc<=0 then
if math.min(dVc,-gVc)<VUc then
bVc=true
else
cVc[#cVc+1]={i=fVc,unknown=iVc,left=gVc}
end
end
end
end
local jVc,kVc=nil,0.25
if bVc then
kVc=0.05
else
if#cVc>0 then
PLc.miss(UUc,cVc,WUc,ZUc)
end
local lVc=0
for mVc,nVc in ipairs(YUc)do
if nVc~=UUc then
local oVc=PLc.ripeValue(nVc,ZUc,_Uc,0.05)
if oVc>lVc then
jVc,lVc=nVc,oVc
end
end
end
if not jVc then
local pVc,qVc=PLc.nextRipe(YUc,ZUc,_Uc,UUc)
local rVc=PLc.hopLead()+0.1
if not UUc then
jVc=pVc or PLc.biggest(YUc)
elseif pVc and pVc~=UUc and qVc<=rVc then
jVc=pVc
end
if qVc then
kVc=qVc-rVc
end
end
end
if jVc then
if PLc.goTo(jVc)then
UUc,TUc=jVc,0
else
TUc=TUc+1
if TUc>=3 then
if type(QUc)==EQd[106]then
QUc.cooldown=10
end
break
end
end
task.wait(0.05)
else
task.wait(math.clamp(kVc,0.05,0.25))
end
PLc.beat=os.clock()
end
OLc.working=false
return os.clock()-SUc>=0.5
end
function PLc.runJob(sVc,tVc)
local uVc,vVc=pcall(PLc.run,sVc,tVc)
OLc.working,PLc.cur=false,nil
