elseif Yad-Gad>2 then
Wad=EQd[625]
break
end
if Yad-Uad>=0.5 then
local Zad,_ad,abd=dZc.smeltSpare(Nad,math.max(dZc.runLoaded or 0,Kad-jb.n(EQd[282])))
Pad,Uad,dZc.smeltSrc=_ad,Yad,abd
if abd then
Tad=true
end
end
local bbd,cbd=jb.n(EQd[2828]),jb.n(EQd[282])
if bbd>=Jad-1 then
Wad=EQd[2861]
break
end
if math.max(dZc.runLoaded or 0,bbd-Lad)>=Sad then
Wad=EQd[2860]
break
end
local dbd=Jad-bbd
if cbd<1 or cbd-Pad<dbd+dZc.smeltMargin(dbd)then
Wad=EQd[2876]
break
end
if Vad and Yad-math.max(Vad,dZc.loadedAt or 0)>4 then
Wad=EQd[1440]
break
end
dZc.smeltBeat=Yad
task.wait(0.1)
end
local ebd=Vad and(os.clock()-Vad)or 0
dZc.leavePad(Wad)
dZc.smelting,dZc.smeltEndAt=false,os.clock()
local fbd=dZc.runLoaded or 0
local gbd=false
if fbd<=0 and Vad then
gbd=true
fbd=math.max(0,Kad-jb.n(EQd[282]),jb.n(EQd[2828])-Lad)
local hbd=math.max(0.5,dZc.call(EQd[2877],cb)or 12)
fbd=math.min(fbd,math.max(0,Jad-Lad)+ebd*math.max(0,Jad)/hbd)
if fbd>0 then
cZc.stats.loaded=dZc.num(cZc.stats.loaded,0)+fbd-math.max(0,dZc.runLoaded or 0)
dZc.fbLeft=fbd
end
end
if Vad then
dZc.padMiss=0
elseif Wad==EQd[625]or Wad==EQd[648]then
dZc.padMiss=(dZc.padMiss or 0)+1
if dZc.padMiss>=3 then
dZc.padMiss=0
dZc.smeltFail(EQd[2872])
end
end
if fbd>0 then
cZc.stats._padFails,dZc.reachNoted=0,nil
if ebd>=0.5 then
local ibd=fbd/ebd
local jbd=dZc.num(cZc.stats._loadRate,nil)
cZc.stats._loadRate=jbd and(jbd*0.7+ibd*0.3)or ibd
end
dZc.smeltSum.magma=dZc.smeltSum.magma+fbd
pcall(F.spend,EQd[1083],EQd[2878],fbd,EQd[282])
elseif Wad==EQd[1440]then
dZc.smeltFail(EQd[2879])
end
if Tad and Vad and type(Nad)==EQd[106]and Nad.id==EQd[1003]then
local kbd=math.max(0,dZc.num(Rad,0))
local lbd,mbd=pcall(dZc.lendAdd,Nad,fbd-kbd,dZc.num(Nad.short,0))
mbd=lbd and dZc.num(mbd,0)or 0
dZc.lendDue={g=Nad,out=kbd,snap=fbd,base=gbd and fbd or 0,runAt=Gad,left=math.max(0,dZc.num(Nad.short,0)-mbd),at=os.clock()+2.2}
pcall(dZc.holdLent)
end
return os.clock()-Gad>=0.5
end
function dZc.lendSettle()
local nbd=dZc.lendDue
if not nbd or os.clock()<nbd.at then
return
end
dZc.lendDue=nil
if dZc.smelting or dZc.smeltRunAt~=nbd.runAt then
return
end
local obd=math.max(nbd.snap,nbd.base+math.max(0,dZc.runLoaded or 0))
local pbd=math.max(0,obd-nbd.out)-math.max(0,nbd.snap-nbd.out)
if pbd>0 and nbd.left>0 then
dZc.lendAdd(nbd.g,pbd,nbd.left)
end
end
function dZc.smeltRunJob(qbd,rbd)
local sbd,tbd=pcall(dZc.smeltRun,qbd,rbd)
if not sbd then
dZc.smelting,dZc.smeltEndAt=false,os.clock()
dZc.leavePad(EQd[1038])
dZc.padSnag,dZc.padSnagWhy=os.clock()+60,EQd[1038]
F.log(1,EQd[2803],EQd[2880]..tostring(tbd))
if type(qbd)==EQd[106]then
qbd.cooldown=30
end
return false
end
return tbd
end
function dZc.smeltAbort()
