end
end
if#Abd>0 then
F.note(EQd[20],string.format(EQd[2881],table.concat(Abd,EQd[142]),ib.fmt(zbd.spent)))
end
end
function dZc.refused(Dbd,Ebd)
local Fbd=(dZc.fails[Dbd]or 0)+1
dZc.fails[Dbd]=Fbd
F.log(1,EQd[286],tostring(Ebd)..EQd[2698])
