function dZc.buyUp(Gbd)
if dZc.buying then
return false
end
local Hbd=Gbd.up
local Ibd=EQd[247]..tostring(Hbd)
local Jbd=jb.a(Ibd)
if dZc.num(Jbd,0)~=Gbd.level then
return false
end
local Kbd,Lbd=pcall(jb.PC.UpgradeCost,Hbd,Gbd.level)
Lbd=Kbd and dZc.num(Lbd,nil)or nil
if not Lbd or Lbd>Gbd.cost*1.0001 then
return false
end
if dZc.spare(Gbd.id)<Lbd then
return false
end
dZc.buying=true
local Mbd=jb.fire(EQd[285],Hbd,false)
local Nbd=os.clock()
if Mbd then
repeat
task.wait(0.15)
until jb.a(Ibd)~=Jbd or os.clock()-Nbd>2 or not F.alive
end
dZc.buying=false
if Mbd and jb.a(Ibd)~=Jbd then
local Obd=jb.n(Ibd)
dZc.fails[Gbd.id]=nil
gb.totals.upgrades=(tonumber(gb.totals.upgrades)or 0)+1
F.log(1,EQd[286],string.format(EQd[2883],tostring(Hbd),math.floor(Obd),ib.fmt(Lbd)))
dZc.boardNote(Hbd,Obd,Lbd)
return true
end
if Mbd then
dZc.refused(Gbd.id,(dZc.NAMES[Hbd]or tostring(Hbd))..EQd[173]..(Gbd.level+1))
end
return false
end
function cZc.tierRise(Pbd)
Pbd=tonumber(Pbd)
if not(jb.PC and Pbd)then
return 0,0,0,0
end
local Qbd=dZc.autoMine()
local Rbd={[EQd[1924]..math.floor(Pbd)]=true}
local Sbd,Tbd=dZc.model(nil,Qbd),dZc.model(Rbd,Qbd)
local Ubd=(dZc.shareNow()*(Tbd.R-Sbd.R)+(Tbd.auto-Sbd.auto))*dZc.calib()*dZc.credit()
if Ubd~=Ubd then
Ubd=0
end
local Vbd,Wbd=dZc.magmaRate(nil),dZc.magmaRate(Rbd)
local Xbd=(Vbd and Wbd and Wbd>Vbd)and(Wbd-Vbd)or 0
local Ybd,Zbd=dZc.ingotRate(nil),dZc.ingotRate(Rbd)
local _bd=(Ybd and Zbd and Zbd>Ybd)and(Zbd-Ybd)or 0
return math.max(0,Ubd),Ubd,Xbd,_bd
end
function cZc.mixSeen()
