function dZc.floorCalc()
local bdd=jb.PC
if not bdd or not dZc.mineOwned()then
return nil
end
local cdd=jb.n(EQd[219])+1
local ddd,edd=dZc.stairPrice(cdd)
if edd==nil or(edd==EQd[282]and not ddd)then
return nil,true
end
if edd~=EQd[282]then
return nil
end
local fdd
for gdd,hdd in ipairs(type(bdd.Rooms)==EQd[106]and bdd.Rooms or{})do
if type(hdd)==EQd[106]and dZc.num(hdd.step,0)>=cdd and(hdd.world or 1)~=2 and not jb.roomOwned(hdd.id)then
if(hdd.currency or EQd[175])~=EQd[282]then
return nil
end
fdd=hdd
break
end
end
if not fdd then
return nil
end
local idd=dZc.num(fdd.price,nil)
if not idd then
return nil,true
end
local jdd,kdd,ldd
for mdd=cdd,fdd.step do
local ndd,odd=dZc.stairPrice(mdd)
if odd==nil or(odd==EQd[282]and not ndd)then
return nil,true
end
if odd~=EQd[282]then
return nil
end
local pdd,qdd=pcall(bdd.StepBlocked,cb,mdd)
if pdd and qdd then
local rdd=tonumber(string.match(tostring(qdd),EQd[1001]))
if jdd==nil then
jdd=dZc.gateWork()
end
if not(rdd and jdd)then
return nil
end
if not kdd then
kdd,ldd=mdd,rdd
end
end
idd=idd+ndd
end
if not(idd>0)then
return nil
end
local sdd=jb.income()
local tdd={floor=sdd*db.ROOM_GAIN/idd,cap=sdd*db.ROOM_GAIN,room=fdd,need=idd,gated=kdd,gatedLevel=ldd}
local udd,vdd=false,false
if kdd then
udd,vdd=pcall(dZc.gateCovered,tdd)
end
if udd and vdd==true then
tdd.covered=true
local wdd,xdd,ydd=pcall(dZc.nextPackage,fdd)
if wdd and type(xdd)==EQd[106]and dZc.num(ydd,0)>0 then
tdd.next,tdd.nextNeed,tdd.floor=xdd,ydd,sdd*db.ROOM_GAIN/ydd
else
tdd.floor,tdd.cap=0,0
end
end
return tdd
end
function dZc.gateCovered(zdd)
local Add,Bdd=dZc.spare(EQd[2830])
if Add== -math.huge then
return false
end
local Cdd=Add+math.min(dZc.sameHold(zdd.room),Bdd)
local Ddd=0
local Edd=dZc.goalNow()
if type(Edd)==EQd[106]and dZc.num(Edd.short,0)>0 and not Edd.allow and not dZc.lendStop()then
if Edd.must and Edd.heat then
Ddd=dZc.num(Edd.loadM,0)
end
Ddd=math.max(Ddd,dZc.lendOne(Edd),dZc.lendOne(Edd.alt))
end
return Cdd-Ddd>=dZc.num(zdd.need,math.huge)
end
function dZc.nextPackage(Fdd)
local Gdd=jb.PC
local Hdd=math.floor(dZc.num(type(Fdd)==EQd[106]and Fdd.step,0))
if not(Gdd and Hdd>0)then
return nil
end
local Idd
for Jdd,Kdd in ipairs(type(Gdd.Rooms)==EQd[106]and Gdd.Rooms or{})do
local Ldd=type(Kdd)==EQd[106]and dZc.num(Kdd.step,0)or 0
if Ldd>Hdd and(Kdd.world or 1)~=2 and not jb.roomOwned(Kdd.id)and(not Idd or Ldd<dZc.num(Idd.step,0))then
Idd=Kdd
end
end
if not Idd or(Idd.currency or EQd[175])~=EQd[282]then
return nil
end
local Mdd=dZc.num(Idd.price,nil)
if not Mdd then
return nil
end
for Ndd=Hdd+1,math.floor(dZc.num(Idd.step,0))do
local Odd,Pdd=dZc.stairPrice(Ndd)
if Pdd~=EQd[282]or not Odd then
return nil
end
local Qdd,Rdd=pcall(Gdd.StepBlocked,cb,Ndd)
if not Qdd then
return nil
end
if Rdd and not string.match(tostring(Rdd),EQd[2887])then
return nil
end
Mdd=Mdd+Odd
end
if not(Mdd>0)then
return nil
end
return Idd,Mdd
end
