function dZc.floorNow()
local _dd=kb.last and kb.last.at
local aed=jb.n(EQd[219])
local bed=dZc.floorCache
if bed and _dd~=nil and bed.at==_dd and bed.steps==aed and not(bed.v and type(bed.v.room)==EQd[106]and jb.roomOwned(bed.v.room.id))then
