end
local Hed=jb.PC
local Ied=dZc.autoMine()
local Jed=dZc.model(nil,Ied)
local Ked,Led=dZc.shareNow(),dZc.calib()*dZc.credit()
local Med=Ded>0 and dZc.magmaRate(nil)or nil
local Ned=Fed>0 and dZc.ingotRate(nil)or nil
local Oed={}
for Ped,Qed in ipairs(dZc.UPS)do
local Red=type(Hed.Upgrades)==EQd[106]and Hed.Upgrades[Qed]or nil
local Sed=type(Hed.UpgradeRoom)==EQd[106]and Hed.UpgradeRoom[Qed]or nil
local Ted=EQd[2897]..Qed
if type(Red)==EQd[106]and(Red.currency or EQd[282])==EQd[282]and(not Sed or jb.roomOwned(Sed))and not dZc.free(Qed)and not dZc.held(Ted)then
local Ued=jb.n(EQd[247]..Qed)
if Ued<dZc.num(Red.max,0)then
local Ved,Wed=pcall(Hed.UpgradeCost,Qed,Ued)
Wed=Ved and dZc.num(Wed,nil)or nil
if Wed and Wed>0 then
local Xed={[EQd[247]..Qed]=Ued+1}
local Yed=Bed>0 and dZc.rowGain(Jed,Xed,Ied,Ked,Led,Bed,Ced)or 0
local Zed=nil
if Med then
