function rhd.derive(Aid,Bid)
local Cid=jb.PC
local Did=Cid.Pearl
Bid=Bid or{}
local Eid=Bid.x or{}
local Fid=Bid.PearlLevel or Aid.P
local Gid={pearl=Fid}
Gid.T=Aid.T*(Bid.FasterFishing and Cid.FishInterval(Bid.FasterFishing)/Cid.FishInterval(Aid.FF)or 1)*(Eid.TreeFishTime or 1)
local Hid=Aid.lt*(Bid.FishLuck2 and Cid.FishLuck2Mult(Bid.FishLuck2)/Cid.FishLuck2Mult(Aid.FL2)or 1)*((Fid>=2)and 2 or 1)/((Aid.P>=2)and 2 or 1)*(Eid.TreeFishLuck or 1)
if Bid.Found then
Hid=Hid*Cid.FishIndexLuck(Bid.Found)/Cid.FishIndexLuck(Aid.found)
end
Gid.luck=math.max(Hid,1)^Aid.share
Gid.ev=rhd.ev(Gid.luck)
Gid.multEvent=Aid.multEvent*(Bid.MoreFish and Cid.FishMultiplier(Bid.MoreFish)/Cid.FishMultiplier(Aid.MF)or 1)*(Bid.MoreFish2 and Cid.MoreFish2Mult(Bid.MoreFish2)/Cid.MoreFish2Mult(Aid.MF2)or 1)*Cid.PearlFish(Fid)/Cid.PearlFish(Aid.P)*(Eid.TreeFish or 1)
Gid.mult=Gid.multEvent*Aid.bulk
Gid.gfv=Aid.gfv*(Bid.GoldenValue and Cid.GoldenValueMult(Bid.GoldenValue)/Cid.GoldenValueMult(Aid.GV)or 1)*((Fid>=5)and Did.GOLDEN_VALUE_MAX or Did.GOLDEN_VALUE)/((Aid.P>=5)and Did.GOLDEN_VALUE_MAX or Did.GOLDEN_VALUE)*(Eid.TreeGoldenFish or 1)
Gid.gold=(Fid>=2)and(1+(Gid.gfv-1)/Did.GOLDEN_ODDS)or 1
Gid.auto=(Fid>=4)and 1 or((Fid>=1)and Did.AUTO_SLOW or 0)
Gid.raw=Gid.ev*Gid.mult*Gid.gold/math.max(0.05,Gid.T)
Gid.rawEvent=Gid.ev*Gid.multEvent*Gid.gold/math.max(0.05,Gid.T)
local Iid=rhd.L()
Gid.kA=((tonumber(Iid.nAmt)or 0)>=5)and math.clamp(tonumber(Iid.kAmt)or 1,0.25,4)or 1
local Jid=tonumber(Iid.kEV)or 1
Gid.kE=((tonumber(Iid.nEV)or 0)>=1 and math.abs(Jid-1)>0.25)and math.clamp(Jid,0.5,2)or 1
Gid.kI=((tonumber(Iid.nInt)or 0)>=1)and math.clamp(tonumber(Iid.kInt)or 1,0.5,4)or 1
Gid.dock=Gid.raw*Gid.kA*Gid.kE/Gid.kI
Gid.away=Gid.dock*Gid.auto
local Kid=math.clamp(tonumber(Iid.share)or 0.5,0.2,1)
if Iid.bothPaid then
Gid.eff=Gid.dock*Kid+Gid.away
elseif Gid.auto>=1 then
Gid.eff=Gid.dock
else
Gid.eff=Gid.dock*Kid+Gid.away*(1-Kid)
end
return Gid
end
function rhd.model(Lid)
