function rhd.baseRaw(ejd,fjd)
local gjd=jb.PC
ejd=tonumber(ejd)or(kb.last and tonumber(kb.last.I))or jb.income()
local hjd=0
local ijd,jjd=jb.n(EQd[277]),os.clock()
local kjd,ljd=gjd.Upgrades and gjd.Upgrades.FishCash,jb.n(EQd[3046])
local mjd=gjd.UpgradeRoom and gjd.UpgradeRoom.FishCash
if kjd and ljd<(kjd.max or 0)and(not mjd or jb.roomOwned(mjd))then
local njd=rhd.fishCashGain(ejd)or 0
local ojd=gjd.UpgradeCost(EQd[3013],ljd)
if ojd<=ijd then
elseif rhd.free(EQd[3013])then
hjd=math.max(hjd,njd/math.max(ojd-ijd,ojd*0.05))
elseif eb.upgrades~=false then
hjd=math.max(hjd,njd/ojd)
end
end
if eb.tree~=false then
for pjd,qjd in ipairs(kb.last and kb.last.opts or{})do
local rjd=type(qjd)==EQd[106]and tonumber(qjd.cost)
if rjd and rjd>0 and qjd.cur==EQd[277]and type(qjd.bundle)==EQd[106]then
local sjd=tonumber(qjd.gain)or 0
local tjd=type(qjd.bundle.costs)==EQd[106]and tonumber(qjd.bundle.costs.Fish)or 0
if sjd>0 and rjd+tjd>ijd then
hjd=math.max(hjd,sjd/rjd)
end
end
end
end
local ujd=gjd.Pearl
local vjd=ujd and ujd.COST and ujd.COST[4]
if not fjd and vjd and jb.n(EQd[1913])==3 and ub.on(qhd.id)and ijd<vjd and jjd>=(rhd.pearlBackoff or 0)and not(sb.saving and not rhd.L().pearlKept)then
hjd=math.max(hjd,ejd/vjd)
end
return hjd
end
