function rhd.hold(Ljd)
local Mjd=jb.PC
local Njd,Ojd=Mjd.Upgrades and Mjd.Upgrades.FishCash,jb.n(EQd[3046])
if not(Njd and Ojd<(Njd.max or 0))or phd.stats.fishCashOK==false or not rhd.free(EQd[3013])then
