function rhd.indexBonus(Tjd,Ujd,Vjd)
local Wjd,Xjd=jb.PC,rhd.state()
if not Xjd or Ujd<=0 or Tjd.T<=0 then
return 0
end
local Yjd,Zjd=rhd.probs(Tjd.luck),0
for _jd=1,#Wjd.Fish.list do
if not jb.has(Wjd.FishKey(_jd))then
Zjd=Zjd+Yjd[_jd]
end
if Tjd.pearl>=2 and not jb.has(Wjd.GoldKey(_jd))then
Zjd=Zjd+Yjd[_jd]/Wjd.Pearl.GOLDEN_ODDS
end
end
if Zjd<=0 then
return 0
end
local akd=rhd.model({Found=Xjd.found+1})
if not akd then
return 0
end
return Zjd/(Tjd.T*Tjd.kI)*math.max(0,akd.eff-Tjd.eff)*Vjd*Ujd
