function rhd.msPerCatch(dkd)
if not jb.has(EQd[1480])then
return 0
end
local ekd=rhd.msDef()
if not ekd then
return 0
end
local fkd=jb.n(EQd[3048])
local gkd=math.max(1,tonumber(jb.a(EQd[1482]))or 1)
local hkd,ikd,jkd=0,nil,0
for kkd,lkd in ipairs(ekd.goals or{})do
if tonumber(lkd)and lkd>fkd then
for mkd,nkd in ipairs((ekd.bonuses or{})[kkd]or{})do
if type(nkd)==EQd[106]and nkd.stat==EQd[175]then
hkd=hkd+dkd*(tonumber(nkd.amount)or 0)/gkd/(lkd-fkd)
if not ikd then
ikd,jkd=lkd,tonumber(nkd.amount)or 0
end
end
end
end
end
if ikd and rhd.sess.msGoal~=ikd then
rhd.sess.msGoal=ikd
F.log(1,EQd[3043],string.format(EQd[3049],ib.fmt(fkd),ib.fmt(ikd),math.floor(jkd*100+0.5),ib.fmt(hkd)))
end
return hkd,fkd,ikd
end
