end
function rhd.cashSample()
local wkd,xkd,ykd=os.clock(),jb.n(EQd[175]),jb.n(EQd[3046])
local zkd=rhd.spendSig()
local Akd=rhd.cw
if not Akd or ykd~=Akd.lvl or wkd-Akd.last>3 or wkd-Akd.t0>600 then
rhd.cw={t0=wkd,last=wkd,cash=xkd,sig=zkd,lvl=ykd,earn=0,hud=0,kept=0}
return
end
local Bkd=wkd-Akd.last
local Ckd=jb.income()
local Dkd,Ekd=pcall(jb.PC.TickInterval,jb.n(EQd[221]))
Ekd=(Dkd and tonumber(Ekd))or 1
local Fkd=rhd.cwList[#rhd.cwList]
local Gkd=math.max(1,((Fkd and Fkd.r)or 1)*1.25)
if phd.onSpot and zkd==Akd.sig and xkd>=Akd.cash and xkd-Akd.cash<=1.5*Gkd*Ckd*(Bkd+Ekd)then
Akd.earn=Akd.earn+(xkd-Akd.cash)
Akd.hud=Akd.hud+Ckd*Bkd
Akd.kept=Akd.kept+Bkd
end
Akd.cash,Akd.last,Akd.sig=xkd,wkd,zkd
if Akd.kept>=20 and Akd.hud>0 then
ib.push(rhd.cwList,{r=Akd.earn/Akd.hud,lvl=ykd,at=wkd},12)
rhd.cw={t0=wkd,last=wkd,cash=xkd,sig=zkd,lvl=ykd,earn=0,hud=0,kept=0}
end
end
function rhd.cwMean(Hkd,Ikd)
local Jkd,Kkd=0,0
for Lkd= #rhd.cwList,1,-1 do
local Mkd=rhd.cwList[Lkd]
if Mkd.lvl==Hkd and(not Ikd or Mkd.at>Ikd)then
Jkd,Kkd=Jkd+Mkd.r,Kkd+1
if Kkd>=4 then
break
end
end
end
if Kkd<2 then
return nil,Kkd
end
return Jkd/Kkd,Kkd
end
