end
function rhd.fcDone(Okd,Pkd,Qkd,Rkd,Skd)
rhd.fc=nil
rhd.fcBefore(Rkd)
local Tkd,Ukd=phd.stats,rhd.L()
Ukd.fcPend=nil
local Vkd=Tkd.fishCashOK
local Wkd=string.format(EQd[3055],math.floor(Qkd.lvl0),math.floor(Rkd))
local Xkd=tonumber(Qkd.hudAttrK)or tonumber(Qkd.hudK)or 1
if Okd==true then
Ukd.fcNo=0
Tkd.fishCashOK=true
Tkd.fishCashAttr=(Pkd==EQd[3056])and(Qkd.hudAttr or EQd[3057])or EQd[3058]
F.log(1,EQd[3043],string.format(EQd[3059],Wkd,Pkd==EQd[3056]and(EQd[3060]..Tkd.fishCashAttr)or EQd[3061],(Pkd==EQd[3056]and Qkd.hudAttr)or EQd[3062],Xkd,tonumber(Skd)or 1))
if Vkd~=true then
F.note(EQd[51],Pkd==EQd[3056]and string.format(EQd[3063],rhd.x(Xkd))or EQd[3064])
end
elseif Okd==false then
Ukd.fcNo=(tonumber(Ukd.fcNo)or 0)+1
F.log(1,EQd[3043],string.format(EQd[3065],Wkd,tonumber(Qkd.hudK)or 1,tonumber(Skd)or 1,math.floor(Ukd.fcNo)))
if Ukd.fcNo>=2 and Vkd~=false then
Tkd.fishCashOK,Tkd.fishCashAttr=false,EQd[576]
F.note(EQd[51],EQd[3066])
end
else
F.log(1,EQd[3043],EQd[3067]..Wkd..EQd[3068])
end
F.saveSoon()
end
function rhd.fcTick()
local Ykd=jb.n(EQd[3046])
local Zkd=jb.n(EQd[98])
local _kd=rhd.L()
local ald=rhd.fc
if ald and(Ykd<=ald.lvl0 or Zkd~=ald.reb)then
F.log(2,EQd[3043],string.format(EQd[3069],math.floor(ald.lvl0),math.floor(Ykd)))
rhd.fc,ald,_kd.fcPend=nil,nil,nil
rhd.fcBefore(Ykd)
end
if not ald and not rhd.fcLvl then
local bld=(type(_kd.fcPend)==EQd[106]and _kd.fcPend)or _kd.fcSave
if type(bld)==EQd[106]and tonumber(bld.lvl0)and type(bld.hud0)==EQd[106]and Ykd>bld.lvl0 and tonumber(bld.reb)==Zkd and os.time()-(tonumber(bld.t)or 0)<600 then
local cld={}
for dld,eld in ipairs(rhd.HUD_ATTRS)do
cld[eld]=tonumber(bld.hud0[eld])or 1
end
rhd.fc={lvl0=bld.lvl0,hud0=cld,at=os.clock()-3,lvl1=Ykd,reb=Zkd}
_kd.fcPend={lvl0=bld.lvl0,hud0=cld,t=tonumber(bld.t)or os.time(),reb=Zkd}
ald=rhd.fc
else
_kd.fcPend=nil
end
end
if not ald then
if rhd.fcLvl and rhd.fcHud and Ykd>rhd.fcLvl and rhd.fcReb==Zkd then
local fld,gld=rhd.cwMean(rhd.fcLvl)
rhd.fc={lvl0=rhd.fcLvl,hud0=rhd.fcHud,at=rhd.fcAt or os.clock(),lvl1=Ykd,r0=fld,n0=gld,reb=Zkd}
_kd.fcPend={lvl0=rhd.fcLvl,hud0=rhd.fcHud,t=os.time(),reb=Zkd}
ald=rhd.fc
else
rhd.fcBefore(Ykd)
local hld=(type(_kd.fcSave)==EQd[106]and _kd.fcSave)or{}
hld.lvl0,hld.hud0,hld.t,hld.reb=Ykd,rhd.fcHud,os.time(),Zkd
_kd.fcSave=hld
return
end
end
if Ykd~=ald.lvl1 then
ald.lvl1,ald.after=Ykd,os.clock()
end
local ild=os.clock()-ald.at
if ild<3 then
return
end
local jld=jb.PC
local kld=jld.FishCashMult(Ykd)/jld.FishCashMult(ald.lvl0)
local lld,mld=jb.income(),jb.income(ald.hud0)
ald.hudK=(mld>0)and lld/mld or 1
local nld=rhd.hudSnap()
ald.hudAttr,ald.hudAttrK=nil,nil
for pld,qld in ipairs(rhd.HUD_ATTRS)do
if ald.hud0[qld]>0 and math.abs(nld[qld]/ald.hud0[qld]/kld-1)<0.02 then
ald.hudAttr,ald.hudAttrK=qld,nld[qld]/ald.hud0[qld]
break
end
end
if ald.hudAttr or math.abs(ald.hudK/kld-1)<0.02 then
rhd.fcDone(true,EQd[3056],ald,Ykd)
return
end
local rld,sld=rhd.cwMean(Ykd,ald.after or ald.at)
if ald.r0 and rld then
local tld=rld/ald.r0
if tld>=1.1 then
rhd.fcDone(true,EQd[3070],ald,Ykd,tld)
return
end
if tld<1.05 and ald.hudK<1.005 and(ald.n0 or 0)>=3 and sld>=3 then
rhd.fcDone(false,nil,ald,Ykd,tld)
return
end
end
if ild>900 then
rhd.fcDone(nil,nil,ald,Ykd)
end
end
function rhd.learn(uld,vld,wld,xld)
local yld=rhd.L()
local zld=(tonumber(yld[vld])or 0)+1
local Ald=1/math.min(zld,xld or 20)
yld[vld]=zld
yld[uld]=(tonumber(yld[uld])or wld)*(1-Ald)+wld*Ald
return zld
end
function rhd.caughtOnDock()
rhd.lastDockCatch=os.clock()
rhd.dry=nil
local Bld=rhd.L()
if phd.onSpot and rhd.curV then
Bld.spot=rhd.curV
end
Bld.dryStays,Bld.dryAt=0,nil
end
function rhd.onCaught(Cld,Dld,Eld,Fld,Gld,Hld)
local Ild,Jld=phd.stats,jb.PC
Dld=tonumber(Dld)or 0
Ild.fish=Ild.fish+Dld
if(tonumber(Hld)or 0)>0 then
return
end
Ild.catches=Ild.catches+1
if Fld then
Ild.golden=Ild.golden+1
end
local Kld=Jld and Jld.Fish and Jld.Fish.list[tonumber(Cld)or 0]
if Eld then
Ild.newFish=Ild.newFish+1
local Lld=rhd.newBatch or{at=os.clock(),names={}}
rhd.newBatch=Lld
Lld.names[#Lld.names+1]=(Fld and EQd[3071]or EQd[146])..(Kld and tostring(Kld.name)or EQd[3072])
end
if Gld then
Ild.anywhereCatches=Ild.anywhereCatches+1
if phd.onSpot then
if rhd.stay then
rhd.stay.auto=rhd.stay.auto+1
end
else
local Mld=rhd.L()
Mld.awayN=(tonumber(Mld.awayN)or 0)+1
end
return
end
if not phd.onSpot then
return
end
rhd.caughtOnDock()
if not Kld then
return
end
local Nld=rhd.model()
if not Nld then
return
end
rhd.sess.dockCatches=rhd.sess.dockCatches+1
rhd.sess.dockFish=rhd.sess.dockFish+Dld
local Old=os.clock()
local Pld=rhd.stay
if Pld then
if not Pld.T or math.abs(Nld.T/Pld.T-1)>0.01 then
Pld.T,Pld.n,Pld.first=Nld.T,0,nil
end
Pld.n,Pld.first,Pld.last=Pld.n+1,Pld.first or Old,Old
end
local Qld=(tonumber(Kld.value)or 0)*Nld.multEvent*(Fld and Nld.gfv or 1)
local Rld=rhd.L()
if Qld>0 and Dld>0 and rhd.learn(EQd[3073],EQd[3074],Dld/Qld)==5 and math.abs(Rld.kAmt-1)>0.1 then
F.log(1,EQd[3043],string.format(EQd[3075],Rld.kAmt))
end
Rld.evV=(tonumber(Rld.evV)or 0)*0.995+(tonumber(Kld.value)or 0)
Rld.evE=(tonumber(Rld.evE)or 0)*0.995+Nld.ev
if Nld.ev>0 and Rld.evE>=100*Nld.ev then
local Sld=Rld.kEV==nil
Rld.kEV,Rld.nEV=Rld.evV/Rld.evE,1
if Sld then
F.log(1,EQd[3043],string.format(EQd[3076],Rld.kEV))
end
end
if not rhd.sess.firstCatch then
rhd.sess.firstCatch=true
F.log(1,EQd[3043],string.format(EQd[3077]..EQd[3078],tostring(Kld.name),rhd.fr(Dld),rhd.fr(Qld),Old-(phd.spotSince or Old),Nld.T,rhd.fr(Nld.rawEvent)))
end
end
function rhd.connect()
if phd.conn or not jb.R then
return
end
local Tld=jb.R:FindFirstChild(EQd[3079])
if not Tld then
if not rhd.sess.noRemote then
rhd.sess.noRemote=true
F.log(1,EQd[3043],EQd[3080])
end
return
end
local Wld,Xld=pcall(function()
return Tld.OnClientEvent:Connect(function(...)
local Uld,Vld=pcall(rhd.onCaught,...)
if not Uld then
F.log(2,EQd[3043],EQd[3081]..tostring(Vld))
end
end)
end)
if Wld and Xld then
phd.conn=Xld
table.insert(F.conns,Xld)
end
end
function rhd.inZone(Yld,Zld)
local _ld=Yld.CFrame:PointToObjectSpace(Zld)
local amd=Yld.Size/2
return math.abs(_ld.X)<=amd.X and math.abs(_ld.Z)<=amd.Z and _ld.Y> -1 and _ld.Y<8
end
function rhd.onSpot(bmd)
local emd,fmd=pcall(function()
for cmd,dmd in ipairs(bb:GetTagged(EQd[3082]))do
if dmd:IsA(EQd[237])and rhd.inZone(dmd,bmd.Position)then
return true
end
end
return false
end)
return emd and fmd==true
end
function rhd.dockStair()
local gmd=jb.PC
local hmd=gmd and gmd.RoomById and gmd.RoomById[rhd.room()]
local imd=hmd and gmd.Steps and gmd.Steps[hmd.step]
return imd and imd.pos or nil
end
function rhd.dockGuess()
local pmd,qmd=pcall(function()
local jmd=workspace:FindFirstChild(EQd[346])
local kmd=jmd and jmd:FindFirstChild(EQd[447])
local lmd=kmd and kmd:FindFirstChild(EQd[413])
local mmd=lmd and lmd:FindFirstChild(EQd[3083])
if not mmd and lmd then
for nmd,omd in ipairs(lmd:GetChildren())do
if omd.Name:match(EQd[3084])then
mmd=omd
break
end
end
end
return mmd and mmd:GetPivot().Position or nil
end)
if pmd and typeof(qmd)==EQd[315]then
return qmd
end
return rhd.dockStair()
end
function rhd.spotPoint(rmd,smd,tmd)
local umd=(tmd==2)and math.min(smd.Y/2+3,6)or((tmd==3)and 1.5 or 3.5)
return rmd:PointToWorldSpace(Vector3 .new(0,umd,0))
end
function rhd.place(vmd,wmd)
local xmd=rhd.spotPoint(vmd.CFrame,vmd.Size,wmd)
rhd.stream(xmd)
rhd.pivot(xmd)
end
function rhd.pickZone(ymd)
local zmd,Amd
for Bmd,Cmd in ipairs(bb:GetTagged(EQd[3082]))do
if Cmd:IsA(EQd[237])and Cmd:IsDescendantOf(workspace)and not rhd.w2(Cmd.Position)then
local Dmd=ymd and(Cmd.Position-ymd).Magnitude or 0
if not Amd or Dmd<Amd then
zmd,Amd=Cmd,Dmd
end
end
end
return zmd
end
function rhd.tryPick(Emd)
local Fmd,Gmd=pcall(rhd.pickZone,Emd)
return Fmd and Gmd or nil
end
function rhd.findZone(Hmd)
local Imd=(phd.zoneCF and phd.zoneCF.Position)or rhd.dockGuess()
local Jmd=rhd.tryPick(Imd)
if not Jmd and Hmd then
if Imd then
rhd.stream(Imd)
Jmd=rhd.tryPick(Imd)
end
if not Jmd and phd.zoneCF then
local Kmd=rhd.L()
phd.zoneCF,phd.zoneSize,Kmd.zone,Kmd.zoneSize=nil,nil,nil,nil
F.log(1,EQd[3043],EQd[3085])
Imd=rhd.dockGuess()
if Imd then
rhd.stream(Imd)
Jmd=rhd.tryPick(Imd)
end
end
if not Jmd and not rhd.stop()then
local Lmd=rhd.dockStair()
if Lmd then
rhd.stream(Lmd)
rhd.pivot(Lmd+Vector3 .new(0,3.5,0))
task.wait(0.8)
rhd.beat=os.clock()
Jmd=rhd.tryPick(Imd or Lmd)
end
end
end
if Jmd then
local Mmd=phd.zone~=Jmd
phd.zone,phd.zoneCF,phd.zoneSize=Jmd,Jmd.CFrame,Jmd.Size
if Mmd then
local Nmd=rhd.L()
Nmd.zone={Jmd.CFrame:GetComponents()}
Nmd.zoneSize={Jmd.Size.X,Jmd.Size.Y,Jmd.Size.Z}
F.log(2,EQd[3043],string.format(EQd[3086],Jmd.Position.X,Jmd.Position.Y,Jmd.Position.Z,Jmd.Size.X,Jmd.Size.Y,Jmd.Size.Z))
end
end
return Jmd
end
function rhd.jobPos()
local Omd=math.clamp(math.floor(tonumber(rhd.L().spot)or 1),1,3)
local Pmd=phd.zone
local Qmd,Rmd
if Pmd and Pmd.Parent then
Qmd,Rmd=Pmd.CFrame,Pmd.Size
elseif phd.zoneCF and phd.zoneSize then
Qmd,Rmd=phd.zoneCF,phd.zoneSize
end
if Qmd then
return rhd.spotPoint(Qmd,Rmd,Omd)-Vector3 .new(0,3.5,0)
end
return rhd.dockStair()
end
function rhd.stop()
return not F.alive or rhd.locked()or jb.busy()~=nil or not ub.on(phd.id)or not jb.roomOwned(rhd.room())
end
function rhd.block(Smd,Tmd,Umd)
phd.blockedUntil,phd.blockedWhy=os.clock()+Smd,Tmd
if Umd or rhd.sess.lastBlock==Tmd then
F.log(1,EQd[3043],Tmd)
else
rhd.sess.lastBlock=Tmd
F.note(EQd[51],Tmd)
end
end
function rhd.dryNow()
local Vmd=rhd.L()
return(tonumber(Vmd.dryStays)or 0)>=2 and os.time()-(tonumber(Vmd.dryAt)or 0)<1800
end
function rhd.gapMax()
local Wmd=rhd.model()
return math.max(5,(Wmd and Wmd.T*Wmd.kI)or 5)
end
function rhd.dryStep(Xmd)
local Ymd=rhd.model()
if not Ymd then
return nil
end
local Zmd=phd.conn~=nil
if not Zmd and Ymd.auto>0 then
return nil
end
local _md=rhd.dry
if not _md or _md.v~=rhd.curV then
rhd.dry={v=rhd.curV,secs=0,tried=_md and _md.tried or{},caught0=jb.n(EQd[3079])}
_md=rhd.dry
end
if not Zmd and jb.n(EQd[3079])>(_md.caught0 or 0)then
rhd.caughtOnDock()
return nil
end
_md.secs=_md.secs+Xmd
local bnd=math.max(4*Ymd.T*Ymd.kI,12)
if _md.secs<=bnd then
return nil
end
_md.tried[_md.v]=true
for cnd=1,2 do
local dnd=(_md.v-1+cnd)%3+1
if not _md.tried[dnd]then
F.log(1,EQd[3043],string.format(EQd[3087],math.floor(bnd)))
return dnd
end
end
local fnd=rhd.L()
fnd.dryStays,fnd.dryAt=(tonumber(fnd.dryStays)or 0)+1,os.time()
rhd.dry=nil
local gnd=(fnd.dryStays>=2)and 1800 or 600
F.log(1,EQd[3043],string.format(EQd[3088],math.floor(bnd),math.floor(fnd.dryStays)))
rhd.block(gnd,EQd[3089]..ib.secs(gnd))
return EQd[3090]
end
function rhd.leaveSpot()
phd.onSpot=false
local hnd=rhd.stay
rhd.stay=nil
if not hnd then
return
end
if hnd.n>=3 and hnd.first and hnd.last>hnd.first and(tonumber(hnd.T)or 0)>0 then
local ind=math.clamp((hnd.last-hnd.first)/(hnd.n-1)/hnd.T,0.25,8)
if rhd.learn(EQd[3091],EQd[3092],ind,5)==1 or math.abs(ind-1)>0.25 then
F.log(1,EQd[3043],string.format(EQd[3093],ind,math.floor(hnd.n)))
end
end
if hnd.auto>3 and not rhd.L().bothPaid then
rhd.L().bothPaid=true
F.log(1,EQd[3043],EQd[3094])
end
end
function rhd.shareStep()
local jnd=os.clock()
local knd=math.min(120,jnd-(rhd.shAt or jnd))
rhd.shAt=jnd
local lnd=math.max(0,math.min(knd,(rhd.spotSecs or 0)-(rhd.spotSecs0 or 0)))
rhd.spotSecs0=rhd.spotSecs or 0
if knd<=0 then
return
end
local mnd=rhd.L()
local nnd=tonumber(mnd.share)or 0.5
mnd.share=math.clamp(nnd+(lnd/knd-nnd)*math.min(1,knd/1800),0.05,1)
end
function rhd.flushNew()
local ond=rhd.newBatch
if not ond or os.clock()-ond.at<60 then
return
end
rhd.newBatch=nil
F.note(EQd[3095],string.format(EQd[3096],table.concat(ond.names,EQd[142]),0.1* #ond.names))
end
function rhd.report(pnd,qnd,rnd)
if pnd<20 then
return
end
local snd=rhd.model()
if not snd then
return
end
local tnd=rhd.sess.reported and 2 or 1
rhd.sess.reported=true
F.log(tnd,EQd[3043],string.format(EQd[3097]..EQd[3098],math.floor(qnd),math.floor(pnd),rhd.fr(rnd/pnd),rhd.fr(snd.rawEvent),snd.kA,snd.kE,snd.kI))
end
function rhd.dockLoop(und,vnd)
local wnd=jb.PC
if not wnd then
return false
end
vnd=math.clamp(tonumber(vnd)or 30,1,600)
local xnd=os.clock()
rhd.connect()
if rhd.stop()then
return false
end
rhd.beat,phd.working=os.clock(),true
local ynd=rhd.findZone(true)
if not ynd then
rhd.block(120,EQd[3099])
return false
end
rhd.curV=(rhd.dry and rhd.dry.v)or math.clamp(math.floor(tonumber(rhd.L().spot)or 1),1,3)
local znd,And,Bnd,Cnd=0,0,nil,os.clock()
local Dnd,End,Fnd=0,rhd.sess.dockCatches,rhd.sess.dockFish
while F.alive and os.clock()-xnd<vnd do
rhd.beat,phd.working=os.clock(),true
rhd.shareStep()
rhd.flushNew()
rhd.flushBoards()
pcall(rhd.cashSample)
pcall(rhd.fcTick)
if rhd.stop()then
break
end
local Gnd=os.clock()
local Hnd=math.min(1,Gnd-Cnd)
Cnd=Gnd
local Ind=jb.root()
if not Ind then
if phd.onSpot then
rhd.leaveSpot()
end
Bnd=Bnd or Gnd
if Gnd-Bnd>12 then
rhd.block(30,EQd[3100],true)
break
end
task.wait(0.5)
elseif Ind.Anchored or rhd.w2(Ind.Position)then
rhd.block(30,EQd[3101],true)
break
else
Bnd=nil
if not ynd:IsDescendantOf(workspace)then
ynd=rhd.findZone(true)
if not ynd then
rhd.block(120,EQd[3099])
break
end
end
if rhd.onSpot(Ind)then
if not phd.onSpot then
if rhd.dry and Gnd-(rhd.lastOnSpot or-1e9)>rhd.gapMax()then
rhd.dry.secs=0
end
phd.onSpot,phd.spotSince,znd=true,Gnd,0
rhd.stay={n=0,auto=0}
rhd.lastOnSpot=Gnd
task.wait(0.3)
else
Dnd=Dnd+Hnd
rhd.spotSecs=(rhd.spotSecs or 0)+Hnd
rhd.lastOnSpot=Gnd
local Jnd=rhd.dryStep(Hnd)
if Jnd==EQd[3090]then
break
elseif Jnd then
rhd.curV=Jnd
rhd.place(ynd,Jnd)
task.wait(0.6)
else
task.wait(0.3)
end
end
else
if phd.onSpot then
rhd.leaveSpot()
if(tonumber(vb.lockN)or 0)==0 and not jb.busy()then
And=And+1
end
end
if And>=6 then
rhd.block(300,EQd[3102])
break
end
if znd>=3 then
local Knd=ynd.CFrame:PointToObjectSpace(Ind.Position)
F.log(1,EQd[3043],string.format(EQd[3103],Knd.X,Knd.Y,Knd.Z,ynd.Size.X,ynd.Size.Y,ynd.Size.Z))
rhd.block(300,EQd[3104])
break
end
if znd>0 then
rhd.curV=rhd.curV%3+1
end
znd=znd+1
rhd.place(ynd,rhd.curV)
task.wait(0.6)
end
end
end
if phd.onSpot then
rhd.leaveSpot()
end
phd.onSpot,phd.working=false,false
rhd.report(Dnd,rhd.sess.dockCatches-End,rhd.sess.dockFish-Fnd)
return os.clock()-xnd>=vnd-0.5
end
function rhd.nextDue()
if not(phd.working and phd.onSpot)then
return nil
end
local Lnd=rhd.model()
if not Lnd then
return nil
end
local Mnd=Lnd.T*Lnd.kI
if Mnd<=0 then
return nil
end
local Nnd,Ond=os.clock(),phd.spotSince
local Pnd=rhd.lastDockCatch
local Qnd=(Pnd and Ond and Pnd>=Ond)and Pnd or Ond
if not Qnd then
return nil
end
local Rnd=Qnd+Mnd-Nnd
if Rnd< -Mnd then
return nil
end
return math.max(0,Rnd),Mnd
end
function rhd.abortDock()
if phd.onSpot then
pcall(rhd.leaveSpot)
end
phd.onSpot,phd.working=false,false
end
function rhd.runDock(Snd,Tnd)
local Und,Vnd=pcall(rhd.dockLoop,Snd,Tnd)
if phd.onSpot then
pcall(rhd.leaveSpot)
end
phd.onSpot,phd.working=false,false
if not Und then
phd.blockedUntil,phd.blockedWhy=os.clock()+60,EQd[3105]
local Wnd=tostring(Vnd)
F.log(rhd.sess.lastErr==Wnd and 2 or 1,EQd[3043],EQd[3106]..Wnd)
rhd.sess.lastErr=Wnd
return false
end
return Vnd==true
end
function rhd.boardBought(Xnd,Ynd,Znd)
local _nd=rhd.boards or{at=os.clock(),fish=0,list={}}
rhd.boards=_nd
_nd.list[Xnd],_nd.fish=Ynd,_nd.fish+(tonumber(Znd)or 0)
end
function rhd.flushBoards()
local aod=rhd.boards
if not aod or os.clock()-aod.at<60 then
return
end
rhd.boards=nil
local bod={}
for cod,dod in pairs(aod.list)do
bod[#bod+1]=(rhd.NAMES[cod]or tostring(cod))..EQd[173]..tostring(dod)
end
table.sort(bod)
F.note(EQd[51],EQd[3107]..table.concat(bod,EQd[142])..EQd[1116]..ib.fmt(aod.fish)..EQd[3108])
end
function rhd.buyUp(eod)
local fod=eod.up
local god=EQd[247]..tostring(fod)
local hod,iod=jb.a(god),jb.n(EQd[277])
if iod<eod.cost then
return false
end
if fod~=EQd[3013]and rhd.hold(eod.cost)then
return false
end
if not jb.fire(EQd[285],fod,false)then
return false
end
local jod=os.clock()
repeat
task.wait(0.15)
until jb.a(god)~=hod or os.clock()-jod>2 or not F.alive
if jb.a(god)~=hod then
local kod=jb.n(god)
gb.totals.upgrades=(tonumber(gb.totals.upgrades)or 0)+1
F.log(1,EQd[286],string.format(EQd[3109],tostring(fod),math.floor(kod),ib.fmt(eod.cost)))
if fod==EQd[3013]then
F.note(EQd[51],string.format(EQd[3110],math.floor(kod),rhd.x(jb.PC.FishCashMult(kod)),ib.fmt(eod.cost)))
else
rhd.boardBought(fod,math.floor(kod),eod.cost)
end
return true
end
