function rhd.pearlBoard()
local function pod()
local qod=workspace:FindFirstChild(EQd[346])
local rod=qod and qod:FindFirstChild(EQd[455])
local sod=rod and rod:FindFirstChild(EQd[413])
local tod=sod and sod:FindFirstChild(EQd[3112])
local uod=tod and tod:FindFirstChild(EQd[3113])
local vod=uod and uod:FindFirstChild(EQd[3114])
local wod=vod and vod:FindFirstChild(EQd[3115])
if not(wod and wod:IsA(EQd[237]))then
