local Bod=Aod and zod.Steps and zod.Steps[Aod.step]
if not(Bod and Bod.pos)or not rhd.hopKeys(Bod.pos)then
return nil
end
task.wait(0.8)
xod,yod=pcall(pod)
if xod and yod then
return yod
end
return Bod.pos
end
function rhd.hopKeys(Cod,Dod)
if not Dod then
rhd.stream(Cod)
end
local Eod,Fod=cb.Character,jb.root()
if F.yielding()or not(Eod and Fod)then
return false
end
local God=pcall(function()
Fod.AssemblyLinearVelocity=Vector3 .zero
Eod:PivotTo(CFrame.new(Cod+Vector3 .new(0,3.5,0)))
end)
return God
end
function rhd.awaken(Hod,Iod,Jod)
