return EQd[3116]
end
if Kod then
rhd.stream(Kod)
if not rhd.hopKeys(rhd.floor(Kod),true)and F.yielding()then
return EQd[3116]
end
task.wait(0.6)
end
if F.yielding()then
return EQd[3116]
end
local Lod=jb.n(EQd[277])
rhd.awakeHave=Lod
F.note(EQd[2998],string.format(EQd[3117],tostring(Iod),ib.fmt(Lod),ib.fmt(Jod),(Hod+1<=3)and EQd[3118]or EQd[146]))
jb.fire(EQd[3119])
local Mod=os.clock()
repeat
task.wait(0.2)
until jb.n(EQd[1913])>Hod or os.clock()-Mod>5 or not F.alive
nb.back=true
return jb.n(EQd[1913])>Hod
end
function rhd.rebuild(Nod,Ood)
local Pod=jb.PC
local Qod=phd.stats.fishCashOK~=false
local Rod={MoreFish=jb.n(EQd[3032]),FasterFishing=jb.n(EQd[3031]),FishCash=Qod and jb.n(EQd[3046])or 0}
local Sod={MoreFish=0,FasterFishing=0,FishCash=0}
local Tod=rhd.model({PearlLevel=Nod,MoreFish=0,FasterFishing=0})
local Uod=Tod and tonumber(Tod.eff)or 0
if not(Uod>0 and Uod<math.huge)then
return nil
end
local Vod,Wod=Pod.FishMultiplier(0),Pod.FishInterval(0)
local function Xod(Yod,Zod)
return Uod*Pod.FishMultiplier(Yod)/Vod*Wod/Pod.FishInterval(Zod)
end
local _od=Xod(Rod.MoreFish,Rod.FasterFishing)
local apd=Pod.FishCashMult(Rod.FishCash)
local bpd={}
for cpd,dpd in ipairs(rhd.BOARD1)do
bpd[dpd]=rhd.free(dpd)
end
local epd,fpd,gpd,hpd=0,0,0,0
for ipd=1,100 do
local jpd,kpd
for lpd,mpd in ipairs(rhd.BOARD1)do
if Sod[mpd]<Rod[mpd]then
local npd=tonumber(Pod.UpgradeCost(mpd,Sod[mpd]))or math.huge
if not kpd or npd<kpd then
jpd,kpd=mpd,npd
end
end
end
if not jpd then
break
end
local opd=Xod(Sod.MoreFish,Sod.FasterFishing)
local ppd=math.min(math.max(0,kpd-fpd)/opd,rhd.H-epd)
gpd=gpd+(_od-opd)*ppd
if Rod.FishCash>0 then
hpd=hpd+(tonumber(Ood)or 0)*(1-Pod.FishCashMult(Sod.FishCash)/apd)*ppd
end
epd=epd+ppd
if epd>=rhd.H then
break
end
if bpd[jpd]then
fpd=kpd
else
fpd,gpd=0,gpd+kpd
end
Sod[jpd]=Sod[jpd]+1
end
return gpd,hpd/rhd.H
end
function rhd.pearlHold(qpd,rpd,spd)
if not rhd.hold(spd)then
return false
end
local tpd=tonumber(jb.PC.UpgradeCost(EQd[3013],jb.n(EQd[3046])))or 0
if tpd<=spd then
return false
end
return(rhd.fishCashGain(qpd)or 0)*spd>(tonumber(rpd)or 0)*(tpd-spd)
end
function rhd.pearlOption(upd)
local vpd=jb.PC
local wpd=vpd.Pearl
if not wpd then
return nil
end
local xpd=os.clock()
if xpd<(rhd.pearlBackoff or 0)or xpd<(rhd.pearlNext or 0)then
return nil
end
local ypd=rhd.model()
if not ypd then
return nil
end
local zpd=ypd.pearl
local Apd=vpd.PearlCost(zpd)
if not Apd then
return nil
end
local Bpd=rhd.pearlName(zpd+1)
if sb.saving and not rhd.L().pearlKept then
rhd.pearlWhy=EQd[1988]..Bpd..EQd[3120]
return nil
end
local Cpd=rhd.pearlBase(upd,zpd+1)
local Dpd=rhd.model({PearlLevel=zpd+1})
if not Dpd then
return nil
end
upd=tonumber(upd)or 0
local Epd=math.max(0,Dpd.eff-ypd.eff)*rhd.H*Cpd
if zpd+1==4 then
Epd=Epd+upd
end
if zpd+1==3 or zpd+1==5 then
Epd=Epd+upd*db.SUPPORT_GAIN
end
if zpd+1<=3 then
local Fpd,Gpd,Hpd=pcall(rhd.rebuild,zpd+1,upd)
if not Fpd or Gpd==nil then
if not Fpd then
F.log(2,EQd[3043],EQd[3121]..tostring(Gpd))
end
rhd.pearlWhy=EQd[1988]..Bpd..EQd[3122]
return nil
end
Epd=Epd-(tonumber(Gpd)or 0)*Cpd-(tonumber(Hpd)or 0)
end
local Ipd=jb.n(EQd[277])
local Jpd=math.max(Apd*rhd.PEARL_FLOOR,Ipd)
if Epd<=0 or Epd/Jpd<Cpd then
rhd.pearlWhy=EQd[1988]..Bpd..EQd[3123]
return nil
end
if zpd>=3 and rhd.pearlHold(upd,Epd,Ipd)then
rhd.pearlWhy=EQd[1988]..Bpd..EQd[3124]
return nil
end
rhd.pearlWhy=nil
return{id=EQd[3125],cur=EQd[277],cost=Jpd,total=Ipd,gain=Epd,accel=true,pearl=zpd+1,label=EQd[1988]..Bpd..EQd[3126],buy=rhd.buyPearl}
end
function rhd.buyPearl(Kpd)
local Lpd=jb.PC
if not ub.on(qhd.id)then
