local Ppd=rhd.pearlName(Mpd+1)
if not Npd or Opd<Npd*rhd.PEARL_FLOOR then
return false
end
local Qpd=os.clock()
if Qpd<(rhd.pearlNext or 0)or Qpd<(rhd.pearlBackoff or 0)then
return false
end
if sb.saving and not rhd.L().pearlKept then
return false
end
local Rpd=(tonumber(Kpd.gain)or 0)/math.max(Npd,Opd)
if Rpd<rhd.pearlBase(nil,Kpd.pearl)then
rhd.pearlWhy=EQd[1988]..Ppd..EQd[3123]
