end
if Mpd>=3 and rhd.pearlHold(nil,Kpd.gain,Opd)then
rhd.pearlWhy=EQd[1988]..Ppd..EQd[3124]
return false
end
local Spd=Mpd+1<=3
local Tpd=jb.PC.Boards and jb.PC.Boards.Fish or{}
local Upd=tonumber(kb.rate.Fish)or 0
if Upd<=0 then
local Vpd=rhd.model()
Upd=Vpd and Vpd.eff or 0
end
for Wpd,Xpd in ipairs(kb.last and kb.last.opts or{})do
local Ypd=(type(Xpd.up)==EQd[120]and Xpd.up)or(Xpd.kind==EQd[264]and Xpd.id)or nil
local Zpd=not(Spd and Ypd and table.find(Tpd,Ypd))
if Xpd.cur==EQd[277]and Xpd.id~=Kpd.id and Zpd and(tonumber(Xpd.ratio)or 0)>Rpd and Upd>0 and((tonumber(Xpd.cost)or 0)-Opd)/Upd<=rhd.H then
rhd.pearlWhy=EQd[1988]..Ppd..EQd[3127]..rhd.rowName(Xpd)
