end
end
if F.yielding()then
rhd.pearlWhy=EQd[1988]..Ppd..EQd[3128]
return false
end
local _pd=jb.root()
if not _pd then
return false
end
if rhd.w2(_pd.Position)then
rhd.pearlWhy=EQd[1988]..Ppd..EQd[3129]
