end
rhd.pearlNext,rhd.pearlWhy,rhd.awakeHave=os.clock()+rhd.PEARL_WAIT,nil,nil
local aqd,bqd,cqd=tonumber(jb.a(EQd[229]))or 1,jb.income(),jb.n(EQd[3046])
local dqd,eqd
rhd.awaking=Ppd
if type(vb.with)==EQd[188]then
dqd,eqd=vb.with(EQd[3130]..Ppd,rhd.awaken,Mpd,Ppd,Npd)
else
dqd,eqd=pcall(rhd.awaken,Mpd,Ppd,Npd)
end
rhd.awaking=nil
if dqd and eqd==EQd[3116]then
rhd.pearlNext,rhd.pearlWhy=nil,EQd[1988]..Ppd..EQd[3128]
return false
end
local fqd=tonumber(rhd.awakeHave)or Opd
if not(dqd and eqd==true)then
rhd.pearlNext,rhd.pearlBackoff=nil,os.clock()+rhd.PEARL_RETRY
if not dqd then
F.log(1,EQd[3043],EQd[3131]..tostring(eqd))
end
local gqd=jb.n(EQd[277])<Opd
if gqd then
pcall(F.spend,EQd[2998],EQd[1988]..Ppd..EQd[3126],fqd,EQd[277])
end
F.note(EQd[2998],EQd[1988]..Ppd..EQd[3132]..(gqd and EQd[3133]or EQd[2702])..EQd[3134])
return false
end
Kpd.total=fqd
rhd.pearlNext=os.clock()+rhd.PEARL_WAIT
qhd.stats.pearls=(tonumber(qhd.stats.pearls)or 0)+1
F.note(EQd[2998],EQd[1988]..Ppd..EQd[3135]..(rhd.PEARL_TEXT[Mpd+1]or EQd[3136]))
F.log(1,EQd[3043],string.format(EQd[3137],Ppd,ib.fmt(fqd),ib.fmt(jb.n(EQd[277])),ib.fmt(Npd),math.floor(cqd),math.floor(jb.n(EQd[3046]))))
if Mpd+1==4 then
task.wait(1.5)
local hqd=tonumber(jb.a(EQd[229]))or 1
local iqd=jb.income()/math.max(1e-9,bqd)
rhd.L().pearl4=iqd
F.log(1,EQd[3043],string.format(EQd[3138],aqd,hqd,iqd))
F.note(EQd[2998],(iqd>1.5)and EQd[3139]or EQd[3140])
end
F.saveSoon()
return true
end
