F.log(1,EQd[3043],string.format(EQd[3153]..EQd[3154],jrd.T,jrd.luck,math.floor(jb.PC.FishLuckShare(cb)*100+0.5),jrd.ev,jrd.mult,jrd.gold,rhd.fr(jrd.raw),rhd.fr(jrd.raw*jrd.auto)))
