function tb.growth()
local Dwd=tb.H
if Dwd.gr and os.clock()-Dwd.gr.at<30 then
return Dwd.gr
end
local Ewd={at=os.clock()}
local Fwd=os.time()
local Gwd=type(gb.ips)==EQd[106]and gb.ips or{}
local Hwd=tb.income()
local Iwd
for Jwd= #Gwd,1,-1 do
local Kwd=Gwd[Jwd]
local Lwd,Mwd=tonumber(type(Kwd)==EQd[106]and Kwd.t),tonumber(type(Kwd)==EQd[106]and Kwd.v)
if Lwd and Mwd and Mwd>0 then
if Fwd-Lwd>3900 then
break
end
Iwd={t=Lwd,v=Mwd}
end
end
if Iwd and Fwd-Iwd.t>=300 and Hwd>0 then
local Nwd=Fwd-Iwd.t
Ewd.ratio=Hwd/Iwd.v
Ewd.span=Nwd>=3300 and EQd[3285]or(EQd[3286]..tb.short(Nwd))
end
local Owd,Pwd,Qwd,Rwd,Swd,Twd=0,0,0,0,0,nil
for Uwd= #Gwd,1,-1 do
local Vwd=Gwd[Uwd]
local Wwd,Xwd=tonumber(type(Vwd)==EQd[106]and Vwd.t),tonumber(type(Vwd)==EQd[106]and Vwd.v)
if Wwd and Xwd and Xwd>0 then
if Fwd-Wwd>2700 then
break
end
local Ywd,Zwd=Wwd-Fwd,math.log(Xwd)
Owd+=1
Pwd+=Ywd
Qwd+=Zwd
Rwd+=Ywd*Ywd
Swd+=Ywd*Zwd
Twd=Wwd
end
end
if Owd>=4 and Twd and Fwd-Twd>=240 then
local _wd=Owd*Rwd-Pwd*Pwd
if _wd>0 then
Ewd.k=(Owd*Swd-Pwd*Qwd)/_wd
end
end
Dwd.gr=Ewd
return Ewd
end
function tb.etaGrowth(axd)
local bxd=tb.growth()
if bxd.k==nil then
return nil,EQd[3287]
end
if bxd.k<=1e-6 then
return nil,EQd[3288]
end
if not(axd and axd>1)then
return 0
end
return math.log(axd)/bxd.k
end
