end
pAd[#pAd+1]={t=tAd,v=uAd}
end
end
if#pAd<2 then
return nil
end
local vAd={}
for wAd= #pAd,1,-1 do
vAd[#vAd+1]=pAd[wAd]
end
local xAd,yAd=vAd[1].t,math.max(oAd,vAd[#vAd].t)
local zAd=yAd-xAd
if zAd<60 then
return nil
end
local AAd={{x=0,v=vAd[1].v,t=xAd}}
local BAd=math.clamp(math.floor(zAd/30),2,tb.CHART_N-1)
local CAd=2
for DAd=1,BAd do
local EAd=xAd+zAd*DAd/BAd
local FAd
while CAd<= #vAd and(vAd[CAd].t<=EAd or DAd==BAd)do
FAd=vAd[CAd]
CAd+=1
end
if FAd then
AAd[#AAd+1]={x=(FAd.t-xAd)/zAd,v=FAd.v,t=FAd.t}
end
end
return{cols=AAd,t0=xAd}
end
