function tb.drawChart()
local HEd=tb.H.chart
if not(HEd and HEd.plot)then
return
end
local IEd,JEd=HEd.plot.AbsoluteSize.X,HEd.plot.AbsoluteSize.Y
if IEd<20 or JEd<20 then
return
end
local KEd=type(gb.ips)==EQd[106]and gb.ips or{}
local LEd=KEd[#KEd]
local MEd= #KEd..EQd[139]..tb.plain(type(LEd)==EQd[106]and LEd.t or EQd[146])
local NEd=math.floor(IEd)..EQd[3441]..math.floor(JEd)
local OEd=HEd.at and(os.clock()-HEd.at)or math.huge
if not(NEd~=HEd.sizeSig or(OEd>=30 and(MEd~=HEd.dataSig or OEd>=300)))then
return
end
HEd.at,HEd.sizeSig,HEd.dataSig=os.clock(),NEd,MEd
local PEd=tb.chartData()
local QEd=PEd~=nil and#PEd.cols>=2
HEd.hasData=QEd
HEd.empty.Visible=not QEd
HEd.dot.Visible=QEd
HEd.ring.Visible=QEd
HEd.cursor.Visible=false
HEd.tip.Visible=false
HEd.pts={}
if not QEd then
for REd,SEd in ipairs(HEd.fill)do
SEd.Visible=false
end
for TEd,UEd in ipairs(HEd.segs)do
UEd.Visible=false
end
for VEd=1,#HEd.grid do
HEd.grid[VEd].Visible=false
HEd.ylab[VEd].Visible=false
end
for WEd,XEd in ipairs(HEd.xlab)do
XEd.Text=EQd[146]
end
tb.set(HEd.note,EQd[3246],EQd[146])
return
end
local YEd,ZEd=math.huge,-math.huge
for _Ed,aFd in ipairs(PEd.cols)do
aFd.l=math.log10(math.max(aFd.v,1))
YEd=math.min(YEd,aFd.l)
ZEd=math.max(ZEd,aFd.l)
end
if ZEd-YEd<0.5 then
local bFd=(ZEd+YEd)/2
YEd,ZEd=bFd-0.25,bFd+0.25
end
local cFd=(ZEd-YEd)*0.1
YEd,ZEd=YEd-cFd,ZEd+cFd
local function dFd(eFd)
return math.clamp((eFd-YEd)/(ZEd-YEd),0,1)
end
local fFd,gFd=tb.chartMarks(YEd,ZEd)
for hFd=1,#HEd.grid do
local iFd=fFd[hFd]
HEd.grid[hFd].Visible=iFd~=nil
HEd.ylab[hFd].Visible=iFd~=nil
if iFd then
HEd.grid[hFd].Position=UDim2 .new(0,0,1-dFd(iFd),0)
HEd.ylab[hFd].Position=UDim2 .new(0,0,1-dFd(iFd),0)
HEd.ylab[hFd].Text=tb.axis(10^iFd)
end
end
local jFd=PEd.cols
for kFd,lFd in ipairs(jFd)do
lFd.px,lFd.py=lFd.x*IEd,(1-dFd(lFd.l))*JEd
HEd.pts[#HEd.pts+1]={x=lFd.x,y=lFd.py/JEd,v=lFd.v,t=lFd.t}
end
for mFd=1,tb.CHART_N-1 do
local nFd,oFd,pFd=jFd[mFd],jFd[mFd+1],HEd.segs[mFd]
if nFd and oFd then
local qFd,rFd=oFd.px-nFd.px,oFd.py-nFd.py
pFd.Position=UDim2 .new(0,(nFd.px+oFd.px)/2,0,(nFd.py+oFd.py)/2)
pFd.Size=UDim2 .new(0,math.sqrt(qFd*qFd+rFd*rFd)+1.5,0,2)
pFd.Rotation=math.deg(math.atan2(rFd,qFd))
pFd.Visible=true
else
pFd.Visible=false
end
end
local sFd=math.min(tb.FILL_N,math.max(8,math.floor(IEd/4)))
local tFd,uFd=jFd[1].px,jFd[#jFd].px
local vFd=1
local function wFd(xFd)
while vFd< #jFd-1 and jFd[vFd+1].px<xFd do
vFd+=1
end
local yFd,zFd=jFd[vFd],jFd[math.min(vFd+1,#jFd)]
if zFd.px>yFd.px then
return yFd.py+(zFd.py-yFd.py)*math.clamp((xFd-yFd.px)/(zFd.px-yFd.px),0,1)
end
return yFd.py
end
for AFd=1,tb.FILL_N do
local BFd=HEd.fill[AFd]
local CFd=HEd.canvas and 0 or 3
local DFd=math.max(math.floor((AFd-1)*IEd/sFd+0.5),math.floor(tFd),CFd)
local EFd=math.min(math.floor(AFd*IEd/sFd+0.5),math.ceil(uFd),math.floor(IEd)-CFd)
if AFd<=sFd and EFd>DFd then
local FFd=math.max(wFd(DFd),wFd(EFd))
BFd.Position=UDim2 .new(0,DFd,0,JEd)
BFd.Size=UDim2 .new(0,EFd-DFd,0,math.max(0,JEd-FFd))
BFd.Visible=true
else
BFd.Visible=false
end
end
local GFd,HFd=jFd[1],jFd[#jFd]
local IFd=UDim2 .new(HFd.x,0,1-dFd(HFd.l),0)
HEd.dot.Position=IFd
HEd.ring.Position=IFd
local JFd=math.max(0,os.time()-PEd.t0)
local KFd={JFd,JFd/2,0}
for LFd,MFd in ipairs(HEd.xlab)do
if LFd==2 and KFd[2]<45 then
MFd.Text=EQd[146]
else
MFd.Text=KFd[LFd]<45 and EQd[3442]or(tb.agoShort(KFd[LFd])..EQd[3443])
end
end
tb.set(HEd.note,EQd[3246],string.format(EQd[3444],tb.agoShort(JFd),ib.fmt(GFd.v),ib.fmt(HFd.v),gFd and(EQd[3445]..tb.axis(10^gFd))or EQd[146]))
end
function tb.chartHover(NFd)
local OFd=tb.H.chart
if not OFd or#OFd.pts<2 then
return
end
local PFd=OFd.plot.AbsoluteSize.X
if PFd<=0 then
return
end
local QFd=(NFd-OFd.plot.AbsolutePosition.X)/PFd
local RFd,SFd
for TFd,UFd in ipairs(OFd.pts)do
local VFd=math.abs(UFd.x-QFd)
if not SFd or VFd<SFd then
RFd,SFd=UFd,VFd
end
end
if not RFd then
return
end
local WFd,XFd=RFd.x>0.6,RFd.y<0.5
OFd.cursor.Position=UDim2 .new(RFd.x,0,0,0)
