function F.rejoin()
if F.rejoinBusy or F.offline then
return
end
F.rejoinBusy=true
local XPd,YPd=pcall(F.rejoinRun)
F.rejoinBusy=false
if not XPd then
F.log(1,EQd[165],EQd[3766]..F.cleanErr(YPd))
local ZPd=F.meta().lost
if type(ZPd)==EQd[106]then
if not ZPd.done then
pcall(F.rejoinStop,ZPd,F.lossWords(ZPd)..EQd[3767])
end
if not F.offline then
pcall(F.goOffline,true)
end
end
F.flush()
end
end
